    "full_text": "Bài 2: Các phương pháp lập quẻ bất thường và Lập quẻ bằng đồng xu\n1. Mở đầu và nhắc lại nội dung bài trước\nThời gian bắt đầu: Buổi học bắt đầu lúc 20:20 (theo tài liệu, có thể là thời gian ghi âm hoặc livestream). Giảng viên chào học viên và tiếp tục bài giảng.\nNhắc lại bài trước: \nBài trước đã hướng dẫn phương pháp lập quẻ hữu thường (theo ngày, tháng, giờ động tâm).\nCông thức hữu thường sử dụng ngày, tháng âm lịch và giờ địa chi để tính thượng quái, hạ quái, hào động, quẻ chính, và quẻ biến.\nCó nhắc đến một phương pháp khác là hữu thường theo phút, nhưng ít sử dụng và chủ yếu được dùng trong Dịch Lý Việt Nam. Giảng viên không dạy phương pháp này vì tính thực tiễn thấp, nhưng khuyến khích học viên tự tìm hiểu trong tài liệu nếu muốn.\nTrong Lục Hào, chủ yếu chỉ cần dùng giờ địa chi, không cần đến phút.\nMục tiêu buổi học: \nGiới thiệu các phương pháp lập quẻ khác ngoài hữu thường, bao gồm: \nLập quẻ bất thường (dựa trên số vật, âm thanh, chữ viết, biển số xe, seri tiền, v.v.).\nLập quẻ bằng đồng xu.\nLập quẻ bằng cỏ thi, thẻ, hoặc bài Kinh Dịch.\nLập quẻ dựa trên ngoại ứng (hình ảnh, sự kiện xung quanh).\nNhấn mạnh rằng có vô số cách lập quẻ, miễn là có số hoặc yếu tố để quy ra số, quẻ sẽ được lập và ứng nghiệm nếu nhập tâm.\n\n2. Lập quẻ bất thường: Đếm số vật\nKhái niệm: \nLập quẻ bất thường là phương pháp bất chợt, không phụ thuộc vào ngày, tháng, giờ cố định như hữu thường.\nNguyên tắc: \"Cứ có số là có quẻ\". Bất kỳ thứ gì đếm được (số vật, âm thanh, chữ, v.v.) đều có thể dùng để lập"
