    "summary": "1. Mở đầu và định hướng buổi học\nThời gian bắt đầu: Buổi học bắt đầu lúc 20:44 (theo thời gian ghi trong tài liệu, có thể là thời gian livestream hoặc ghi âm). Giảng viên chào học viên trực tuyến và tại lớp, tạo không khí thân thiện.\nMục tiêu buổi học:\nHoàn thành phần lý thuyết về các thông tin của quẻ (thế, ứng, gia đình quẻ, nạp địa chi).\nChuẩn bị cho buổi học tiếp theo (buổi thứ ba) về giải quẻ, tức là luận giải ý nghĩa quẻ.\nNhắc nhở học viên:\nGiảng viên khuyên học viên Quang Dũng Phạm không cần dùng số tay Kinh Dịch, vì số tay chỉ dành cho người không học Lục Hào. Khi học Lục Hào, học viên cần tập trung vào lý thuyết và thực hành, không phụ thuộc vào tra cứu.\nKhuyến khích học viên chuẩn bị vở ghi chép để ghi lại nội dung, vì sau này khi giải quẻ, ghi chép sẽ giúp tránh quên kiến thức.\n2. Các thông tin của quẻ: Thế và Ứng\nKhái niệm cơ bản:\nTrong một quẻ Lục Hào, hào thế và hào ứng là hai yếu tố quan trọng để luận quẻ.\nHào thế:\nĐại diện cho bản thân người gieo quẻ hoặc người hỏi quẻ.\nLà yếu tố chủ động trong quẻ, thể hiện vị trí của người liên quan trực tiếp đến sự việc.",
