    "full_text": "Ví dụ 3: Quẻ Lôi Trạch Quy Muội\nYêu cầu: Tìm Thế, Ứng, an Địa Chi, an Lục Thân.\nÝ nghĩa phong thủy: \nQuẻ Lôi Trạch Quy Muội thường báo hiệu nhà có vong (linh hồn) hoặc đống lộn xộn (quần áo, sách vở, đồ đạc bừa bộn). Giảng viên khuyến khích “nhắm mắt phán” nhà có vấn đề này, nhưng cần kiểm tra kỹ.\nBước thực hiện: \nTìm Thế và Ứng: \nBiến hào 1, 2, 3, 4, 5 → Chưa ra quẻ thuần.\nBiến lại hào 4 → Chưa ra.\nBiến ba hào cuối (1, 2, 3) → Ra quẻ Thuần Đoài.\nKết luận: Quẻ Lôi Trạch Quy Muội thuộc gia đình Thuần Đoài (ngũ hành Kim), là quẻ Quy Hồn.\nThế ở hào 3, Ứng ở hào 6.\nAn Địa Chi: \nHạ quái (Đoài): Tỵ, Mùi, Dậu.\nThượng quái (Chấn): Ngọ, Thân, Tuất.\nKết quả (từ hào 6 đến hào 1): Tuất, Thân, Ngọ, Dậu, Mùi, Tỵ.\nGhi thêm ngũ hành: \nTỵ: Hỏa.\nMùi: Thổ.\nDậu: Kim.\nNgọ: Hỏa.\nThân: Kim.\nTuất: Thổ.\nAn Lục Thân: \nNgũ hành gốc: Kim.\nSo sánh: \nHào 6 (Tuất, Thổ): Thổ sinh Kim → Phụ Mẫu (sinh ta).\nHào 5 (Thân, Kim): Kim cùng Kim → Huynh Đệ.\nHào 4 (Ngọ, Hỏa): Hỏa khắc Kim → Quan Quỷ (khắc ta).\nHào 3 (Dậu, Kim): Kim cùng Kim → Huynh Đệ.\nHào 2 (Mùi, Thổ): Thổ sinh Kim → Phụ Mẫu.\nHào 1 (Tỵ, Hỏa): Hỏa khắc Kim → Quan Quỷ.\nKết quả: Một số học viên nhầm lẫn, ra quẻ Thuần Chấn thay vì Thuần Đoài. Giảng viên lưu ý: \nBiến đến bước cuối (ba hào 1, 2, 3) phải ra quẻ thuần. Nếu không ra, cần kiểm tra lại từ đầu, vì chắc chắn đã biến sai.\nQuẻ Quy Hồn là quẻ thứ tám trong gia đình, thường mang ý nghĩa đặc biệt."
