    "full_text": "Ví dụ 4: Quẻ Hỏa Thiên Đại Hữu (Bốc tiền)\nYêu cầu: Lập quẻ từ bốc tiền (31) vào 21:06 giờ Hợi, tìm Thế, Ứng, Địa Chi, Lục Thân cho quẻ chính và quẻ biến.\nLập quẻ: \nSố bốc tiền: 31.\nThời gian: 21:06 giờ Hợi (giờ thứ 12 trong ngày).\nTính hào động: \nTổng: 31 + 12 = 43.\nChia cho 6: 43 ÷ 6 = 7 (dư 1) → Hào động là hào 4.\nQuẻ chính: Hỏa Thiên Đại Hữu (quẻ số 31).\nQuẻ biến: Động hào 4 → Quẻ Sơn Thiên Đại Súc.\nBước thực hiện: \nQuẻ chính (Hỏa Thiên Đại Hữu): \nTìm Thế và Ứng: \nBiến hào 1, 2, 3, 4, 5, quay lại hào 4, biến ba hào cuối (1, 2, 3) → Ra quẻ Thuần Ly.\nKết luận: Thuộc gia đình Thuần Ly (ngũ hành Hỏa), là quẻ Quy Hồn.\nThế ở hào 3, Ứng ở hào 6.\nAn Địa Chi: \nHạ quái (Càn): Tý, Dần, Thìn.\nThượng quái (Ly): Mão, Sửu, Hợi.\nKết quả: Hợi, Sửu, Mão, Thìn, Dần, Tý.\nNgũ hành: Tý (Thủy), Dần (Mộc), Thìn (Thổ), Mão (Mộc), Sửu (Thổ), Hợi (Thủy).\nAn Lục Thân: \nNgũ hành gốc: Hỏa.\nSo sánh: \nHào 6 (Hợi, Thủy): Hỏa khắc Thủy → Thê Tài.\nHào 5 (Sửu, Thổ): Thổ khắc Hỏa → Quan Quỷ.\nHào 4 (Mão, Mộc): Mộc sinh Hỏa → Phụ Mẫu.\nHào 3 (Thìn, Thổ): Thổ khắc Hỏa → Quan Quỷ.\nHào 2 (Dần, Mộc): Mộc sinh Hỏa → Phụ Mẫu.\nHào 1 (Tý, Thủy): Hỏa khắc Thủy → Thê Tài.\nQuẻ biến (Sơn Thiên Đại Súc): \nLưu ý: Không cần tìm Thế, Ứng cho quẻ biến, chỉ an Địa Chi và Lục Thân.\nAn Địa Chi: \nHạ quái (Càn): Tý, Dần, Thìn.\nThượng quái (Cấn): Tuất, Tý, Dần.\nKết quả: Dần, Tý, Tuất, Thìn, Dần, Tý.\nNgũ hành: Tý (Thủy), Dần (Mộc), Thìn (Thổ), Tuất (Thổ).\nAn Lục Thân: \nQuan trọng: Lục Thân của quẻ biến theo ngũ hành gốc của quẻ chính ("
