    "hexagrams": [],
    "summary": "1. Mở đầu và định hướng buổi học\nThời gian bắt đầu: Buổi học bắt đầu lúc 0:08 (theo thời gian ghi trong tài liệu, có thể là thời gian ghi âm hoặc livestream). Giảng viên chào học viên trực tuyến và tại lớp, tạo không khí thân thiện.\nMục tiêu buổi học:\nHọc lý thuyết về mối tương quan của 12 địa chi (Tam Hợp, Nhị Hợp, Nhị Xung, Nhập Mộ) để áp dụng vào việc luận quẻ.\nGiới thiệu các khái niệm Vượng Tướng Hưu Tù Tử, Nhật Kiến, Nguyệt Kiến, và Dụng Thần.\nHướng dẫn các bước luận quẻ (từ chọn Dụng Thần đến khai thác thông tin bổ trợ).\nChuẩn bị cho việc thực hành giải quẻ ở các buổi sau.\nNhắc nhở học viên:\nGiảng viên nhấn mạnh rằng các khái niệm hôm nay là nền tảng để giải quẻ, cần ghi chép cẩn thận.\nKhông cần học thuộc, chỉ cần hiểu và thực hành. Sau khi quen, học viên sẽ tự nhiên luận quẻ mà không cần nhớ máy móc.\nMột số nội dung trong lớp khác với các video trên YouTube (do YouTube có yếu tố giải trí), học viên nên ưu tiên cách dạy tại lớp.\n2. Lý thuyết về mối tương quan của 12 địa chi\nGiảng viên giới thiệu các mối tương quan giữa 12 địa chi, được sử dụng để luận quẻ trong Kinh Dịch Lục Hào. Các mối quan hệ chính bao gồm Tam Hợp, Nhị Hợp, Nhị Xung, và Nhập Mộ.\n2.1. Tam Hợp",
    "full_text": "Bài 5: Địa Chi Tương Quan (Tam Hợp, Nhị Hợp, Nhị Xung, Nhập Mộ) và Các Bước Luận Quẻ\n1. Mở đầu và định hướng buổi học\nThời gian bắt đầu: Buổi học bắt đầu lúc 0:08 (theo thời gian ghi trong tài liệu, có thể là thời gian ghi âm hoặc livestream). Giảng viên chào học viên trực tuyến và tại lớp, tạo không khí thân thiện.\nMục tiêu buổi học: \nHọc lý thuyết về mối tương quan của 12 địa chi (Tam Hợp, Nhị Hợp, Nhị Xung, Nhập Mộ) để áp dụng vào việc luận quẻ.\nGiới thiệu các khái niệm Vượng Tướng Hưu Tù Tử, Nhật Kiến, Nguyệt Kiến, và Dụng Thần.\nHướng dẫn các bước luận quẻ (từ chọn Dụng Thần đến khai thác thông tin bổ trợ).\nChuẩn bị cho việc thực hành giải quẻ ở các buổi sau.\nNhắc nhở học viên: \nGiảng viên nhấn mạnh rằng các khái niệm hôm nay là nền tảng để giải quẻ, cần ghi chép cẩn thận.\nKhông cần học thuộc, chỉ cần hiểu và thực hành. Sau khi quen, học viên sẽ tự nhiên luận quẻ mà không cần nhớ máy móc.\nMột số nội dung trong lớp khác với các video trên YouTube (do YouTube có yếu tố giải trí), học viên nên ưu tiên cách dạy tại lớp.\n2. Lý thuyết về mối tương quan của 12 địa chi\nGiảng viên giới thiệu các mối tương quan giữa 12 địa chi, được sử dụng để luận quẻ trong Kinh Dịch Lục Hào. Các mối quan hệ chính bao gồm Tam Hợp, Nhị Hợp, Nhị Xung, và Nhập Mộ.\n2.1. Tam Hợp\nKhái niệm: \n12 địa chi được chia thành bốn nhóm Tam Hợp, mỗi nhóm gồm ba địa chi, tạo thành một cục (Thủy, Hỏa, Kim, Mộc).\nBốn nhóm Tam Hợp: \nThân - Tý - Thìn: Thủy cục (lấy Tý ở giữa làm cục, vì Tý là Thủy).\nDần - Ngọ - Tuất:"
