    "id": 17,
    "lesson_id": 6,
    "lesson_title": "Bài 6: Thực Hành Giải Quẻ Cầu Tài Ngắn Hạn và Luận giải chi tiết",
    "block_name": "Khối 2: Phương pháp Luận & Định lượng Hào lực",
    "case_title": "Bài 6: Thực Hành Giải Quẻ Cầu Tài Ngắn Hạn và Luận giải chi tiết",
    "hexagrams": [
      "Thủy Trạch Tiết"
    ],
    "summary": "1. Mở đầu và định hướng buổi học\nThời gian bắt đầu: Buổi học bắt đầu lúc 0:01 (theo thời gian ghi trong tài liệu, có thể là thời gian ghi âm hoặc livestream). Giảng viên chào học viên trực tuyến và tại lớp, đợi khoảng 1 phút để học viên online tham gia.\nKhông khí lớp học:\nGiảng viên tạo không khí vui vẻ, thân thiện, kể chuyện hài hước về học viên và các quẻ đã luận trước đây (ví dụ: quẻ về dời cây, quẻ về chuyện riêng tư của học viên).\nNhắc đến học viên “Đạo” (học lớp phong thủy cơ bản trước đó), từng hỏi quẻ về “quê có nuôi tôm được không” và được luận chi tiết về việc dời cây trước nhà.\nKể về một học viên nữ hỏi “năm nay có chồng không”, nhưng quẻ tiết lộ thời điểm “lần đầu tiên” của chị với chồng cũ (trước hay sau cưới, cách thời điểm cưới bao lâu), khiến cả lớp bất ngờ về độ chi tiết của Lục Hào.\nGiảng viên hài hước: “Chị em phụ nữ học Lục Hào không cần mặc đồ, vì quẻ moi hết bí mật!” (ám chỉ khả năng khai thác thông tin chi tiết).\nMục tiêu buổi học:\nThực hành giải quẻ cầu tài ngắn hạn (trang 123 trong tài liệu), áp dụng các bước luận quẻ đã học ở buổi 5.\nGiúp học viên làm quen với quy trình luận quẻ qua các ví dụ cụ thể.\nGiới thiệu cách chọn Dụng Thần trong trường hợp có nhiều hào cùng Lục Thân (Dụng Thần lưỡng hiện).\nTập trung vào việc xét Vượng/Suy của Dụng Thần và Hào Thế, kết luận quẻ tốt/xấu, và tìm Ứng Kỳ (thời điểm xảy ra sự việc).\nCung cấp thông tin bổ trợ (phong thủy, vong, di ảnh) dựa trên quẻ.\nNhắc nhở học viên:",
    "full_text": "Bài 6: Thực Hành Giải Quẻ Cầu Tài Ngắn Hạn và Luận giải chi tiết\n1. Mở đầu và định hướng buổi học\nThời gian bắt đầu: Buổi học bắt đầu lúc 0:01 (theo thời gian ghi trong tài liệu, có thể là thời gian ghi âm hoặc livestream). Giảng viên chào học viên trực tuyến và tại lớp, đợi khoảng 1 phút để học viên online tham gia.\nKhông khí lớp học: \nGiảng viên tạo không khí vui vẻ, thân thiện, kể chuyện hài hước về học viên và các quẻ đã luận trước đây (ví dụ: quẻ về dời cây, quẻ về chuyện riêng tư của học viên).\nNhắc đến học viên “Đạo” (học lớp phong thủy cơ bản trước đó), từng hỏi quẻ về “quê có nuôi tôm được không” và được luận chi tiết về việc dời cây trước nhà.\nKể về một học viên nữ hỏi “năm nay có chồng không”, nhưng quẻ tiết lộ thời điểm “lần đầu tiên” của chị với chồng cũ (trước hay sau cưới, cách thời điểm cưới bao lâu), khiến cả lớp bất ngờ về độ chi tiết của Lục Hào.\nGiảng viên hài hước: “Chị em phụ nữ học Lục Hào không cần mặc đồ, vì quẻ moi hết bí mật!” (ám chỉ khả năng khai thác thông tin chi tiết).\nMục tiêu buổi học: \nThực hành giải quẻ cầu tài ngắn hạn (trang 123 trong tài liệu), áp dụng các bước luận quẻ đã học ở buổi 5.\nGiúp học viên làm quen với quy trình luận quẻ qua các ví dụ cụ thể.\nGiới thiệu cách chọn Dụng Thần trong trường hợp có nhiều hào cùng Lục Thân (Dụng Thần lưỡng hiện).\nTập trung vào việc xét Vượng/Suy của Dụng Thần và Hào Thế, kết luận quẻ tốt/xấu, và tìm Ứng Kỳ (thời điểm xảy ra sự việc).\nCung cấp thông tin bổ trợ (phong thủy, vong, di ảnh) dựa trên quẻ."
