    "hexagrams": [],
    "summary": "Các bước luận quẻ:\nChọn Dụng Thần (Thê Tài cho cầu tài).\nXác định Hào Thế, xét tương quan với Dụng Thần (tốt: cùng ngũ hành, tương sinh; xấu: tương khắc).\nXét Vượng/Suy của Dụng Thần (năm, tháng, ngày, theo thứ tự Thái Tuế → Nguyệt/Nhật Kiến → Tam Hợp → Nhị Hợp → Nhị Xung → Nhập Mộ → Ngũ hành).\nXét Vượng/Suy của Hào Thế.\nXét Hào Động và lực/tương tác (sinh/khắc Dụng Thần, Thế).\nKết luận quẻ (tốt/xấu, thành/bại).\nTìm Ứng Kỳ (gặp Trì, gặp Hợp).\nKhai thác thông tin bổ trợ (phong thủy, vong, di ảnh).\nCác khái niệm quan trọng:\nDụng Thần lưỡng hiện: Chọn Hào Động hoặc hào mạnh hơn.\nNhật Kiến/Nguyệt Kiến: Hào trùng ngày/tháng rất Vượng.\nNguyệt Phá/Nhật Phá: Hào bị xung với tháng/ngày → Suy, nếu cả hai thì vô phương cứu chữa.\nỨng Kỳ: Dựa trên Hào Động, gặp Trì (trùng địa chi) hoặc Hợp (Nhị Hợp).",
    "full_text": "Ví dụ 3 (Bĩ Gia Nhân): Quẻ tốt, mùa đông có tiền (tháng 11, 12), kiểm tra bóng đèn/di ảnh bàn thờ.\nCác bước luận quẻ: \nChọn Dụng Thần (Thê Tài cho cầu tài).\nXác định Hào Thế, xét tương quan với Dụng Thần (tốt: cùng ngũ hành, tương sinh; xấu: tương khắc).\nXét Vượng/Suy của Dụng Thần (năm, tháng, ngày, theo thứ tự Thái Tuế → Nguyệt/Nhật Kiến → Tam Hợp → Nhị Hợp → Nhị Xung → Nhập Mộ → Ngũ hành).\nXét Vượng/Suy của Hào Thế.\nXét Hào Động và lực/tương tác (sinh/khắc Dụng Thần, Thế).\nKết luận quẻ (tốt/xấu, thành/bại).\nTìm Ứng Kỳ (gặp Trì, gặp Hợp).\nKhai thác thông tin bổ trợ (phong thủy, vong, di ảnh).\nCác khái niệm quan trọng: \nDụng Thần lưỡng hiện: Chọn Hào Động hoặc hào mạnh hơn.\nNhật Kiến/Nguyệt Kiến: Hào trùng ngày/tháng rất Vượng.\nNguyệt Phá/Nhật Phá: Hào bị xung với tháng/ngày → Suy, nếu cả hai thì vô phương cứu chữa.\nỨng Kỳ: Dựa trên Hào Động, gặp Trì (trùng địa chi) hoặc Hợp (Nhị Hợp).\nThông tin bổ trợ: Kiểm tra phong thủy (phòng khách, bàn thờ, nhà kho), phát hiện vong.\nKế hoạch tiếp theo: \nBuổi sau (tối thứ Tư) sẽ tiếp tục thực hành, giải các quẻ phức tạp hơn.\nSẽ hướng dẫn chi tiết về Ám Động, Tam Hình, cân lực hào, và cách khai thác thông tin bổ trợ (như phát hiện vong).\nGiảng viên hứa cung cấp thêm ví dụ thực tế và bài tập để học viên luyện tập.\n6. Bổ sung giải thích\nTầm quan trọng của thực hành: \nThực hành giúp học viên hiểu rõ cách áp dụng lý thuyết (Tam Hợp, Nhị Hợp, Vượng/Suy) vào luận quẻ.\nCác ví dụ cầu tài ngắn hạn đơn giản, phù hợp cho người mới học, nhưng vẫn thể"
