    "summary": "1. Mở đầu và định hướng buổi học\nThời gian bắt đầu: Buổi học bắt đầu lúc 0:20 (theo thời gian ghi trong tài liệu, có thể là thời gian ghi âm hoặc livestream). Giảng viên chào học viên trực tuyến và tại lớp, tạo không khí thân thiện.\nTình trạng giảng viên: Giảng viên thông báo bị đau chân, nên sẽ ngồi giảng suốt buổi, không di chuyển nhiều.\nMục tiêu buổi học:\nThực hành giải hai ví dụ quẻ cầu tài ngắn hạn (trang 124-125), áp dụng tám bước luận quẻ đã học.\nGiới thiệu lý thuyết mới:\nCân lực của hào: Xác định trạng thái Vượng/Suy của hào dựa trên ngày, tháng, và năm.\nMối tương quan giữa hào động và hào biến: Các trường hợp như Hóa Hợp, Hóa Hồi Đầu Sinh, Hóa Hồi Đầu Khắc, Hóa Xung, Hóa Mộ, Hóa Tuyệt, Hóa Không Vong, Hóa Tiến Thần, Hóa Thoái Thần.\nCủng cố kỹ năng chọn Dụng Thần, xét Vượng/Suy, tìm Ứng Kỳ, và khai thác thông tin bổ trợ (phong thủy, vong).\nNhắc nhở học viên:\nMang tài liệu, đặc biệt là trang 28 (bảng Nhị Hợp, Nhị Xung, Nhập Mộ) và trang 99 (chương Ứng Kỳ) để tra cứu nhanh.\nGhi chép cẩn thận, đặc biệt là các bước luận quẻ và lý thuyết mới.\nHọc viên chưa quen có thể tra bảng tra cứu, không cần học thuộc, chỉ cần hiểu và thực hành.\nLiên hệ qua Facebook Nguyễn Mạnh Cường hoặc Nam Việt Phong Thủy nếu cần hỗ trợ tài liệu.",
