    "full_text": "Ví dụ 5 (Địa Thủy Sư): Quẻ tốt, có lời, Hào Động Huynh Đệ (cướp tài) nhưng mất lực, không ảnh hưởng.\nLý thuyết mới: \nCân lực của hào: Bảy trường hợp xét Vượng/Suy dựa trên ngày, tháng, năm.\nMối tương quan hào động - hào biến: Hóa Hợp, Hóa Hồi Đầu Sinh, Hóa Hồi Đầu Khắc, Hóa Xung, Hóa Mộ, Hóa Tuyệt, Hóa Không Vong, Hóa Tiến Thần, Hóa Thoái Thần.\nCác bước luận quẻ (nhắc lại): \nChọn Dụng Thần (Thê Tài cho cầu tài).\nXác định Hào Thế, xét tương quan với Dụng Thần.\nXét Vượng/Suy của Dụng Thần.\nXét Vượng/Suy của Hào Thế.\nXét Hào Động, lực, và tương tác với Dụng Thần/Thế.\nKết luận quẻ (tốt/xấu).\nTìm Ứng Kỳ (gặp Trì, gặp Hợp).\nKhai thác thông tin bổ trợ.\nCác khái niệm quan trọng: \nHóa Hợp: Vượng, nhưng không tương tác.\nHóa Hồi Đầu Khắc: Mất lực.\nHóa Tuyệt: Thổ hóa Tỵ cần xét cẩn thận (Hóa Hồi Đầu Sinh nếu Vượng, Hóa Tuyệt nếu Suy).\nHóa Tiến Thần: Vượng, có lực.\nHóa Thoái Thần: Mất lực.\nHuynh Đệ động: Tượng cướp tài, nhưng mất lực thì không ảnh hưởng.\nKế hoạch tiếp theo: \nKhóa trung cấp (bắt đầu từ buổi sau) sẽ bồi thêm kiến thức về: \nThông tin bổ trợ chi tiết (phong thủy, ngoại tình, sảy thai).\nKhông Vong, vòng Trường Sinh.\nCác trường hợp hào động - hào biến còn lại.\nLịch học: Thứ Hai, thứ Tư, không nghỉ.\n7. Bổ sung giải thích\nTầm quan trọng của thực hành: \nHai ví dụ giúp học viên củng cố quy trình luận quẻ, đặc biệt là xét Hào Động và Ứng Kỳ.\nLý thuyết cân lực và mối tương quan hào động - hào biến là bước tiến để luận quẻ phức tạp hơn.\nĐiểm độc đáo của Lục Hào: \nKhông chỉ trả lời câu"
