    "id": 24,
    "lesson_id": 8,
    "lesson_title": "Bài 8: Quy Trình Luận Quẻ Sự Nghiệp và Trường Hợp Dụng Thần Lưỡng Hiện",
    "block_name": "Khối 2: Phương pháp Luận & Định lượng Hào lực",
    "case_title": "Bài 8: Quy Trình Luận Quẻ Sự Nghiệp và Trường Hợp Dụng Thần Lưỡng Hiện",
    "hexagrams": [],
    "summary": "1. Giới Thiệu Tổng Quan\nMục tiêu bài giảng: Hướng dẫn học viên áp dụng kỹ thuật luận quẻ Lục Hào để trả lời các câu hỏi về sự nghiệp, cụ thể là khả năng thăng chức, đồng thời củng cố lý thuyết về Dụng Thần, Vượng Suy, và ứng kỳ.\nPhương pháp giảng dạy: Kết hợp lý thuyết và thực hành qua các ví dụ cụ thể, khuyến khích học viên làm bài tập và thảo luận để nắm vững kỹ năng.\nTài liệu tham khảo: Các trang trong sách (trang 69, 151, 152) được đề cập để học viên tra cứu. Bài giảng nhấn mạnh việc đối chiếu sách do các phiên bản in có thể lệch trang.\nNgữ cảnh: Bài giảng thuộc khóa học trung cấp về Dịch lý Việt Nam, tập trung vào Lục Hào, với nội dung kế thừa từ các buổi học trước về Dụng Thần và các khái niệm cơ bản.\n2. Quy Trình Luận Quẻ Lục Hào (Chi Tiết)\nBài giảng trình bày một quy trình luận quẻ gồm 8 bước, được giải thích sâu hơn với các lưu ý thực tiễn và ví dụ minh họa:\nChọn Dụng Thần:\nĐịnh nghĩa: Dụng Thần là hào lục thân đại diện cho vấn đề được hỏi (ví dụ: Quan Quỷ cho sự nghiệp, Thê Tài cho tiền bạc, Tử Tôn cho con cái).\nLưu ý: Phải xác định đúng mục đích của người hỏi. Ví dụ, câu hỏi về \"công việc\" có thể ám chỉ tiền bạc (Thê Tài) hoặc thăng chức (Quan Quỷ).\nVí dụ thực tiễn: Nếu người hỏi nói \"Tôi muốn biết công việc năm nay thế nào\", cần hỏi thêm: \"Anh/chị quan tâm đến thu nhập, thăng chức, hay ổn định công việc?\". Nếu trả lời \"thăng chức\", chọn Quan Quỷ; nếu \"thu nhập\", chọn Thê Tài.\nMẹo: Luôn hỏi lại để tránh chọn sai Dụng Thần, vì sai Dụng Thần dẫn đến kết luận sai.\nXét Trì Thế:\nĐịnh nghĩa: Trì Thế là mối quan hệ giữa hào Thế (đại diện cho người hỏi) và Dụng Thần. Nếu Dụng Thần Trì Thế (nằm ở hào Thế), là tượng tốt; nếu cách xa, là tượng xấu.",
    "full_text": "Bài 8: Quy Trình Luận Quẻ Sự Nghiệp và Trường Hợp Dụng Thần Lưỡng Hiện\n1. Giới Thiệu Tổng Quan\nMục tiêu bài giảng: Hướng dẫn học viên áp dụng kỹ thuật luận quẻ Lục Hào để trả lời các câu hỏi về sự nghiệp, cụ thể là khả năng thăng chức, đồng thời củng cố lý thuyết về Dụng Thần, Vượng Suy, và ứng kỳ.\nPhương pháp giảng dạy: Kết hợp lý thuyết và thực hành qua các ví dụ cụ thể, khuyến khích học viên làm bài tập và thảo luận để nắm vững kỹ năng.\nTài liệu tham khảo: Các trang trong sách (trang 69, 151, 152) được đề cập để học viên tra cứu. Bài giảng nhấn mạnh việc đối chiếu sách do các phiên bản in có thể lệch trang.\nNgữ cảnh: Bài giảng thuộc khóa học trung cấp về Dịch lý Việt Nam, tập trung vào Lục Hào, với nội dung kế thừa từ các buổi học trước về Dụng Thần và các khái niệm cơ bản.\n\n2. Quy Trình Luận Quẻ Lục Hào (Chi Tiết)\nBài giảng trình bày một quy trình luận quẻ gồm 8 bước, được giải thích sâu hơn với các lưu ý thực tiễn và ví dụ minh họa:\nChọn Dụng Thần: \nĐịnh nghĩa: Dụng Thần là hào lục thân đại diện cho vấn đề được hỏi (ví dụ: Quan Quỷ cho sự nghiệp, Thê Tài cho tiền bạc, Tử Tôn cho con cái).\nLưu ý: Phải xác định đúng mục đích của người hỏi. Ví dụ, câu hỏi về \"công việc\" có thể ám chỉ tiền bạc (Thê Tài) hoặc thăng chức (Quan Quỷ).\nVí dụ thực tiễn: Nếu người hỏi nói \"Tôi muốn biết công việc năm nay thế nào\", cần hỏi thêm: \"Anh/chị quan tâm đến thu nhập, thăng chức, hay ổn định công việc?\". Nếu trả lời \"thăng chức\", chọn Quan Quỷ; nếu \"thu nhập\", chọn Thê Tài.\nMẹo: Luôn hỏi lạ"
