    "summary": "5.7. Quẻ Quy Muội và Phệ Hạp\nQuẻ Quy Muội:\nBiểu thị rối ren, mờ ám, chất đống lộn xộn, nhà có vong.\nỨng dụng: Xác nhận rối ren, chất đống, vong qua phỏng vấn người hỏi.\nQuẻ Phệ Hạp:\nBiểu thị khó khăn, trở ngại, cần vượt qua thử thách.\nỨng dụng: Xác nhận tranh cãi, chậm trễ trong công việc.\n6. Ví Dụ Bổ Sung: Quẻ Hôn Nhân (Ngoại Tình)\nThông tin quẻ:\nNgày: Giả định Nhâm Thìn.\nTháng: Tuất.\nQuẻ: Bỉ Tụy.\nCâu hỏi: Hôn nhân (ngoại tình).\nPhân tích:",
    "full_text": "Ví dụ 1: Hào Ngọ trong năm Tý → Tuế Phá, làm Dụng Thần Suy.\n5.7. Quẻ Quy Muội và Phệ Hạp\nQuẻ Quy Muội: \nBiểu thị rối ren, mờ ám, chất đống lộn xộn, nhà có vong.\nỨng dụng: Xác nhận rối ren, chất đống, vong qua phỏng vấn người hỏi.\nQuẻ Phệ Hạp: \nBiểu thị khó khăn, trở ngại, cần vượt qua thử thách.\nỨng dụng: Xác nhận tranh cãi, chậm trễ trong công việc.\n\n6. Ví Dụ Bổ Sung: Quẻ Hôn Nhân (Ngoại Tình)\nThông tin quẻ: \nNgày: Giả định Nhâm Thìn.\nTháng: Tuất.\nQuẻ: Bỉ Tụy.\nCâu hỏi: Hôn nhân (ngoại tình).\nPhân tích: \nDụng Thần: Thê Tài (Mão Mộc, vợ).\nHào động: Tuất Thổ Phụ Mẫu (hào 3, ứng, người khác).\nNhị Hợp: Mão (Thê Tài) hợp Tuất (Phụ Mẫu) → Vợ hợp với người khác (ngoại tình).\nLục Thú: \nTuất lâm Câu Trần → Móc nối, lén lút.\nHuyền Vũ động → Mờ ám, bí mật.\nKhông Vong: Tuất không bị Không Vong, Mão bị Không Vong → Che giấu ngoại tình.\nTháng Tuất nhập quẻ: Việc xảy ra trong tháng.\nNgày Thìn xung Tuất: Phát hiện trong ngày.\nHóa biến: Tuất hóa Mùi (Thoái Thần), nhưng Vượng (Nguyệt Kiên) → Không thoái, bố mẹ ngăn ly hôn.\nHào Thế: Mão (vợ) và hào 3 (chồng) cùng trên giường (hào 3), nhưng Không Vong → Tình cảm lạnh nhạt.\nKết luận: Vợ ngoại tình với cấp trên hoặc người lớn tuổi, bị phát hiện, muốn ly hôn nhưng bố mẹ ngăn, dẫn đến tình cảm lạnh nhạt.\nPhản hồi thực tiễn: Hai vợ chồng vẫn chung nhà, nhưng lạnh nhạt, đúng như luận quẻ.\n\n7. Ứng Dụng Thực Tiễn và Lưu Ý\n7.1. Ứng Dụng trong Luận Quẻ\nChọn Dụng Thần: \nHỏi kỹ mục đích để chọn đúng Dụng Thần.\nDụng Thần Lưỡng Hiện: Ưu tiên hào động, Không V"
