    "full_text": "Bài 10: Vòng Trường Sinh, Nhị Hại, Tam Hình và Ứng Dụng Luận Quẻ Công Danh\n1. Giới Thiệu Tổng Quan\nMục tiêu bài giảng: \nHoàn thiện phân tích ví dụ 2 (quẻ Phệ Hạp, từ buổi trước) và phân tích ví dụ 3 (quẻ Phệ Hạp biến Bỉ) về công danh.\nGiới thiệu lý thuyết Vòng Trường Sinh và cách áp dụng trong luận quẻ.\nGiới thiệu Nhị Hại, Tam Hình, và ứng dụng trong nhận diện tượng sảy thai/bỏ con.\nCủng cố quy trình luận quẻ 8 bước, tích hợp Không Vong, Lục Thú, và xử lý nhiều hào động.\nKhai thác thông tin bổ sung (phong thủy nhà cửa, sảy thai, bỏ con) từ quẻ.\nPhương pháp giảng dạy: \nKết hợp lý thuyết (Vòng Trường Sinh, Nhị Hại, Tam Hình) và thực hành (phân tích ví dụ 2 và 3).\nThảo luận tương tác, khuyến khích ghi chép, đặt câu hỏi, và thực hành.\nSử dụng bảng tra cứu (Vòng Trường Sinh, Lục Thú) và ví dụ thực tiễn để minh họa.\nNgữ cảnh: \nBài giảng thuộc khóa trung cấp Lục Hào, tiếp nối buổi LHNMC 09."
