    "summary": "Giới thiệu Phục Thần và Ám Động để xử lý các trường hợp phức tạp.\nThông điệp của giảng viên:\nHọc Lục Hào cần đi từng bước, không vội vàng, tránh đọc tài liệu ngoài gây nhiễu loạn.\nThực hành luận quẻ và kiểm nghiệm thực tế là yếu tố then chốt để tiến bộ.\nKhuyến khích học viên tương tác, đặt câu hỏi, và tham gia nhóm học.\nNhấn mạnh việc khai thác thông tin bổ sung (phong thủy, sảy thai, ngoại tình) để tăng tính thực tiễn.\n2. Ôn Tập Quy Trình Luận Quẻ Lục Hào\nQuy trình luận quẻ 8 bước được ôn tập và áp dụng trong phân tích ví dụ, tích hợp các yếu tố Không Vong, Lục Thú, Vòng Trường Sinh, và nhiều hào động:\nChọn Dụng Thần: Xác định lục thân đại diện cho vấn đề (Quan Quỷ: công danh, thi cử đối kháng; Phụ Mẫu: thi cử hồ sơ; Thê Tài: tiền bạc; Tử Tôn: con cái; Huynh Đệ: cạnh tranh).\nXét Trì Thế: Đánh giá mối quan hệ giữa hào Thế (người hỏi) và Dụng Thần (gần Thế, tương sinh → tốt; xa Thế, tương khắc → xấu).\nXét Vượng Suy của Dụng Thần: Đánh giá trạng thái Vượng/Suy dựa trên năm, tháng, ngày, Không Vong, Nhị Hợp, Nhị Xung, Nhập Mộ, Thái Tuế, Nguyệt Kiên, Nhật Kiên.\nXét Vượng Suy của Thế: Tương tự Dụng Thần, đánh giá sức mạnh của người hỏi.\nXét Hào Động: Phân tích hào động (Vượng/Suy, hóa biến, tương tác với Dụng Thần/Thế, Lục Thú).\nKết Luận: Tổng hợp để trả lời câu hỏi (Dụng Thần Vượng, Thế Vượng, hào động hỗ trợ → tốt).",
    "full_text": "Ví dụ 1 và 2 tập trung vào thi cử, phân biệt Dụng Thần (Quan Quỷ, Phụ Mẫu) và ứng dụng thực tiễn.\nGiới thiệu Phục Thần và Ám Động để xử lý các trường hợp phức tạp.\nThông điệp của giảng viên: \nHọc Lục Hào cần đi từng bước, không vội vàng, tránh đọc tài liệu ngoài gây nhiễu loạn.\nThực hành luận quẻ và kiểm nghiệm thực tế là yếu tố then chốt để tiến bộ.\nKhuyến khích học viên tương tác, đặt câu hỏi, và tham gia nhóm học.\nNhấn mạnh việc khai thác thông tin bổ sung (phong thủy, sảy thai, ngoại tình) để tăng tính thực tiễn.\n\n2. Ôn Tập Quy Trình Luận Quẻ Lục Hào\nQuy trình luận quẻ 8 bước được ôn tập và áp dụng trong phân tích ví dụ, tích hợp các yếu tố Không Vong, Lục Thú, Vòng Trường Sinh, và nhiều hào động:\nChọn Dụng Thần: Xác định lục thân đại diện cho vấn đề (Quan Quỷ: công danh, thi cử đối kháng; Phụ Mẫu: thi cử hồ sơ; Thê Tài: tiền bạc; Tử Tôn: con cái; Huynh Đệ: cạnh tranh).\nXét Trì Thế: Đánh giá mối quan hệ giữa hào Thế (người hỏi) và Dụng Thần (gần Thế, tương sinh → tốt; xa Thế, tương khắc → xấu).\nXét Vượng Suy của Dụng Thần: Đánh giá trạng thái Vượng/Suy dựa trên năm, tháng, ngày, Không Vong, Nhị Hợp, Nhị Xung, Nhập Mộ, Thái Tuế, Nguyệt Kiên, Nhật Kiên.\nXét Vượng Suy của Thế: Tương tự Dụng Thần, đánh giá sức mạnh của người hỏi.\nXét Hào Động: Phân tích hào động (Vượng/Suy, hóa biến, tương tác với Dụng Thần/Thế, Lục Thú).\nKết Luận: Tổng hợp để trả lời câu hỏi (Dụng Thần Vượng, Thế Vượng, hào động hỗ trợ → tốt).\nỨng Kỳ: Dự đoán thời điểm dựa trên Thái Tuế, hóa biến, Không Vong"
