    "full_text": "Bài 12: Ám Động, Nhật Phá, Nguyệt Phá và Ứng Dụng Luận Quẻ Công Danh, Hôn Nhân\n1. Giới Thiệu Tổng Quan\nMục tiêu bài giảng: \nQuay lại phân tích ví dụ 4 (công danh, ngày Ất Mùi, tháng Thìn, quẻ Địa Hỏa Minh Di) từ LHNMC 11, bổ sung lý thuyết Ám Động.\nPhân tích ví dụ 5 (công danh trọn đời, ngày Ất Mão, tháng Tý, quẻ Hỏa Sơn Lữ).\nPhân tích ví dụ 1 về lo âu chốn quan trường (ngày Mậu Thân, tháng Mùi, quẻ Phong Hỏa Gia Nhân biến Hỏa Sơn Lữ).\nPhân tích ví dụ 1 về hôn nhân (ngày Mậu Mão, tháng Tuất, nam hỏi, quẻ Hỏa Lôi Phệ Hạp).\nGiới thiệu và ứng dụng lý thuyết Ám Động (hào động ngầm do xung ngày/tháng), Nhật Phá, Nguyệt Phá, và trường hợp đặc biệt (hào Lâm Không Vong bị ngày xung).\nCủng cố kỹ năng luận quẻ với nhiều hào động, Nhị Hợp, Không Vong, và Vòng Trường Sinh.\nKhai thác thông tin bổ sung: phong thủy (cây, nước, vong), sảy thai/bỏ con, ngoại tình.\nPhương pháp giảng dạy: \nKết hợp lý thuyết (Ám Động, Nhật/Nguyệt Phá) và thực hành (phân tích ví dụ).\nThảo luận tương tác, khuyến khích ghi chép, đặt câu hỏi, và thực hành.\nSử dụng bảng tra cứu (Vòng Trường Sinh, Lục Thú, Không Vong) và ví dụ thực tiễn.\nNhấn mạnh tư duy logic, kiểm nghiệm thực tế, và đọc tài liệu lý thuyết tại nhà.\nNgữ cảnh: \nBài giảng thuộc khóa trung cấp Lục Hào, tiếp nối LHNMC 11.\nÔn tập quy trình luận quẻ 8 bước và các khái niệm từ LHNMC 11 (Phục Thần, Không Vong, Lục Thú)."
