    "full_text": "Ví dụ 5 (công danh trọn đời) giới thiệu Phục Thần và Ám Động.\nVí dụ lo âu chốn quan trường và hôn nhân nhấn mạnh Dụng Thần, Thế, và ứng kỳ.\nGiảng viên chia sẻ kinh nghiệm thực tiễn (luận ngoại tình, phong thủy, sảy thai) và dự đoán kinh tế (giá vàng lập đỉnh giữa năm 2022).\nThông điệp của giảng viên: \nHọc Lục Hào cần kiên nhẫn, thực hành đều đặn, và kiểm nghiệm thực tế.\nTránh chỉ tập trung vào Dụng Thần mà bỏ qua hào Thế (dẫn đến sai quẻ).\nĐọc tài liệu lý thuyết tại nhà (trang 181-182 về hôn nhân, trang 99 về ứng kỳ).\nTham gia nhóm học, thảo luận, và nghiệm chứng các trường hợp đặc biệt (hào Lâm Không Vong, hào Thổ Ám Động).\nLưu ý khi luận ngoại tình: Cần khéo léo, tránh gây xung đột, đặc biệt khi cả hai vợ chồng có mặt.\n\n2. Ôn Tập Quy Trình Luận Quẻ Lục Hào\nQuy trình luận quẻ 8 bước được áp dụng xuyên suốt, tích hợp Ám Động, Nhật/Nguyệt Phá, Không Vong, Lục Thú, và Vòng Trường Sinh:\nChọn Dụng Thần: Xác định lục thân đại diện cho vấn đề: \nCông danh, thi cử đối kháng: Quan Quỷ.\nThi cử hồ sơ: Phụ Mẫu (phụ).\nHôn nhân (nam hỏi): Thê Tài; (nữ hỏi): Quan Quỷ.\nLo âu chốn quan trường: Hào Thế (người hỏi).\nCon cái: Tử Tôn; tiền bạc: Thê Tài; cạnh tranh: Huynh Đệ.\nXét Trì Thế: Đánh giá mối quan hệ giữa hào Thế (người hỏi) và Dụng Thần: \nGần Thế, tương sinh → Tốt.\nXa Thế, tương khắc → Xấu.\nTử Tôn Trì Thế (hôn nhân) → Xấu.\nXét Vượng Suy của Dụng Thần: Đánh giá trạng thái Vượng/Suy dựa trên: \nNăm, tháng, ngày, Không Vong, Nhị Hợp, Nhị Xung, Nhập Mộ, Thái Tuế, Nguyệt Kiên, Nhật Kiên.\nÁm Độ"
