    "summary": "1. Giới Thiệu Tổng Quan\nMục tiêu bài giảng:\nPhân tích ví dụ 2 (trang 184): Ngày Canh Tý, tháng Dần, nữ hỏi năm nay có bạn trai không (quẻ Hỏa Lôi Phệ Hạp).\nPhân tích ví dụ: Ngày Mậu Dần, tháng Tý, nữ hỏi ly hôn (quẻ Thủy Hỏa Ký Tế).\nPhân tích ví dụ: Ngày Tân Hợi, tháng Tuất, năm Ngọ, nam hỏi mối quan hệ với bạn gái phát triển thế nào (quẻ Trạch Thủy Khốn).\nPhân tích ví dụ: Ngày Mậu Dần, tháng Tý, nữ đoán chồng muốn ly hôn (quẻ Thủy Trạch Tiết biến Thủy Lý).\nCủng cố lý thuyết: Ám Động, Nhật/Nguyệt Phá, Không Vong, Nhị Hợp, và Vòng Trường Sinh.\nỨng dụng thực tiễn: Xác định ngoại tình, phong thủy (cây, nước), quản lý tài chính, và luân thường đạo lý.\nNhấn mạnh tư duy linh hoạt, tránh áp dụng cứng nhắc ngũ hành hoặc quy tắc.\nPhương pháp giảng dạy:\nKết hợp lý thuyết và phân tích ví dụ thực tiễn.\nTương tác qua câu hỏi, thảo luận, và kiểm nghiệm thực tế.\nSử dụng quy trình luận quẻ 8 bước, bảng tra cứu (Vòng Trường Sinh, Lục Thú, Không Vong).\nRút ngắn các bước cơ bản (đã nắm từ LHNMC 12) để tập trung vào ngũ hành, Ám Động, và hào động.",
    "full_text": "Bài 13: Luận Quẻ Tình Duyên và Hôn Nhân (Ngoại Tình, Ly Hôn)\n1. Giới Thiệu Tổng Quan\nMục tiêu bài giảng: \nPhân tích ví dụ 2 (trang 184): Ngày Canh Tý, tháng Dần, nữ hỏi năm nay có bạn trai không (quẻ Hỏa Lôi Phệ Hạp).\nPhân tích ví dụ: Ngày Mậu Dần, tháng Tý, nữ hỏi ly hôn (quẻ Thủy Hỏa Ký Tế).\nPhân tích ví dụ: Ngày Tân Hợi, tháng Tuất, năm Ngọ, nam hỏi mối quan hệ với bạn gái phát triển thế nào (quẻ Trạch Thủy Khốn).\nPhân tích ví dụ: Ngày Mậu Dần, tháng Tý, nữ đoán chồng muốn ly hôn (quẻ Thủy Trạch Tiết biến Thủy Lý).\nCủng cố lý thuyết: Ám Động, Nhật/Nguyệt Phá, Không Vong, Nhị Hợp, và Vòng Trường Sinh.\nỨng dụng thực tiễn: Xác định ngoại tình, phong thủy (cây, nước), quản lý tài chính, và luân thường đạo lý.\nNhấn mạnh tư duy linh hoạt, tránh áp dụng cứng nhắc ngũ hành hoặc quy tắc.\nPhương pháp giảng dạy: \nKết hợp lý thuyết và phân tích ví dụ thực tiễn.\nTương tác qua câu hỏi, thảo luận, và kiểm nghiệm thực tế.\nSử dụng quy trình luận quẻ 8 bước, bảng tra cứu (Vòng Trường Sinh, Lục Thú, Không Vong).\nRút ngắn các bước cơ bản (đã nắm từ LHNMC 12) để tập trung vào ngũ hành, Ám Động, và hào động.\nKhuyến khích học viên ghi chép, đặt câu hỏi, và thực hành gieo quẻ.\nNgữ cảnh: \nBài giảng thuộc khóa trung cấp, tiếp nối LHNMC 12 (trang 165, ví dụ về lo âu chốn quan trường và hôn nhân).\nÔn tập quy trình luận quẻ 8 bước, tập trung vào xử lý Phục Thần, Ám Động, và hào động.\nVí dụ được chọn từ thực tiễn (học viên khóa trước, bạn của học viên Trâm), nhấn mạnh tính ứng dụng.\nGiảng viên chia sẻ"
