    "summary": "Ôn tập lý thuyết:\nQuy trình luận quẻ 8 bước, Vượng/Suy, Ám Động, Nhị Hợp, Không Vong.\nDụng Thần hóa Quan Quỷ hoặc Quan Quỷ hóa Dụng Thần: Tượng đại hung, dễ dẫn đến chết chóc.\nPhản ngâm và phục ngâm:\nPhản ngâm: Quẻ biến thành quẻ tương xung (nội/ngoại quái) hoặc hào biến thành hào xung.\nPhục ngâm: Quẻ đổi nhưng địa chi không đổi, biểu thị lo lắng, rên rỉ.\nTam hợp cục: Sáu trường hợp tạo thành tam hợp cục (đầy đủ, Khuyết, Minh/Ám Động, Nhật/Nguyệt, hào biến, phục thần).\nPhong thủy: Nhà có vong (quẻ Tiểu Quá), cây khắc tài, phương tiện giao thông (Phụ Mẫu).\nỨng dụng thực tiễn:\nDự đoán sinh con, sảy thai, giới tính thai nhi.\nXem xuất hành, mua nhà, lên chức, bổ nhiệm.\nHóa giải quẻ hung: Chặt cây khắc tài, thay sim điện thoại, đặt nước/đá phong thủy.\nKhai thác thông tin bổ sung: Cây bên phải nhà, chân không đi được, phương tiện giao thông trễ giờ.\nCủng cố tư duy:",
    "full_text": "Ví dụ 9 (ngày Đinh Dậu, tháng Tý): Xem bổ nhiệm (quẻ không rõ, tam hợp cục Khuyết).\nÔn tập lý thuyết: \nQuy trình luận quẻ 8 bước, Vượng/Suy, Ám Động, Nhị Hợp, Không Vong.\nDụng Thần hóa Quan Quỷ hoặc Quan Quỷ hóa Dụng Thần: Tượng đại hung, dễ dẫn đến chết chóc.\nPhản ngâm và phục ngâm: \nPhản ngâm: Quẻ biến thành quẻ tương xung (nội/ngoại quái) hoặc hào biến thành hào xung.\nPhục ngâm: Quẻ đổi nhưng địa chi không đổi, biểu thị lo lắng, rên rỉ.\nTam hợp cục: Sáu trường hợp tạo thành tam hợp cục (đầy đủ, Khuyết, Minh/Ám Động, Nhật/Nguyệt, hào biến, phục thần).\nPhong thủy: Nhà có vong (quẻ Tiểu Quá), cây khắc tài, phương tiện giao thông (Phụ Mẫu).\nỨng dụng thực tiễn: \nDự đoán sinh con, sảy thai, giới tính thai nhi.\nXem xuất hành, mua nhà, lên chức, bổ nhiệm.\nHóa giải quẻ hung: Chặt cây khắc tài, thay sim điện thoại, đặt nước/đá phong thủy.\nKhai thác thông tin bổ sung: Cây bên phải nhà, chân không đi được, phương tiện giao thông trễ giờ.\nCủng cố tư duy: \nPhân biệt sức khỏe mẹ/con, con ruột/con nuôi.\nXử lý quẻ phức tạp (nhiều hào động, tam hợp cục).\nNghiệm chứng thực tế qua phong thủy và xuất hành.\nPhương pháp giảng dạy: \nKết hợp lý thuyết và phân tích ví dụ thực tế từ học viên.\nTương tác qua thảo luận, đặt câu hỏi, và kiểm nghiệm tại lớp.\nSử dụng bảng tra cứu (Vòng Trường Sinh, Lục Thú, Không Vong, Dịch Mã, Hậu Thiên Bát Quái).\nKhuyến khích học viên thực hành, ghi chép, đọc tài liệu (trang 89, 200, tam hợp cục).\nNhấn mạnh kiểm tra Ám Động, cân lực Vượng/Suy, và xử lý tam hợp cục trước"
