    "summary": "Ứng dụng thực tiễn:\nDự đoán thời điểm hành nhân (chồng, con, cháu) trở về.\nXác định hung hiểm (tai nạn, chết chóc) thông qua Dụng Thần Suy, Bạch Hổ, và quẻ Cấn.\nNhận diện dấu hiệu ngoại tình qua Thê Tài, Quan Quỷ, và Nhị Hợp.\nKết hợp phong thủy (đào hoa, hướng nhà) để giải thích tình huống.\nÔn tập lý thuyết:\nDụng Thần:\nQuan Quỷ: Đại diện cho chồng, người đi xa.\nTử Tôn: Đại diện cho con, cháu.\nVượng/Suy:\nVượng: Được tháng/ngày sinh, Nhị Hợp, Ám Động.\nSuy: Bị tháng/ngày khắc, Nhật/Nguyệt Phá, Không Vong, Nhập Mộ.\nNhị Hợp:\nTăng lực Vượng, nhưng có thể “tham hợp quên sinh/khắc”.",
    "full_text": "Ví dụ 5: Xem bán đất (quẻ không rõ, liên quan đến Ngọ-Mùi Nhị Hợp).\nỨng dụng thực tiễn: \nDự đoán thời điểm hành nhân (chồng, con, cháu) trở về.\nXác định hung hiểm (tai nạn, chết chóc) thông qua Dụng Thần Suy, Bạch Hổ, và quẻ Cấn.\nNhận diện dấu hiệu ngoại tình qua Thê Tài, Quan Quỷ, và Nhị Hợp.\nKết hợp phong thủy (đào hoa, hướng nhà) để giải thích tình huống.\nÔn tập lý thuyết: \nDụng Thần: \nQuan Quỷ: Đại diện cho chồng, người đi xa.\nTử Tôn: Đại diện cho con, cháu.\nVượng/Suy: \nVượng: Được tháng/ngày sinh, Nhị Hợp, Ám Động.\nSuy: Bị tháng/ngày khắc, Nhật/Nguyệt Phá, Không Vong, Nhập Mộ.\nNhị Hợp: \nTăng lực Vượng, nhưng có thể “tham hợp quên sinh/khắc”.\nHợp tàng khắc (Tý-Sửu, Tỵ-Thân): Hợp ban đầu, sau khắc.\nHợp sinh (Ngọ-Mùi, Dần-Hợi): Hợp và hỗ trợ lẫn nhau.\nỨng kỳ: Giải hợp bằng Xung (ví dụ: Tý-Sửu hợp → Ngọ/Mùi xung).\nỨng kỳ: \nDựa trên Trì/Hợp/Xung, Không Vong, Nguyệt Phá.\nKhông Vong: Ứng khi Xuất Không (ngày/tháng hợp/xung).\nNguyệt Phá: Ứng Trì/Hợp (ví dụ: Tý trong tháng Ngọ → Ứng Tý/Sửu).\nPhong thủy: \nHào 2: Nhà, đường nhỏ.\nHào 3: Cửa, cổng, toilet.\nHào 5: Đường lớn.\nĐào hoa (Mộc Dục): Dễ ngoại tình, liên quan đến hướng nhà.\nHung hiểm: \nDụng Thần Suy, bị khắc/xung, Thái Tuế xung (Tuế Phá).\nHào Thế/Ứng Lâm Bạch Hổ: Tang chế, máu me, tai nạn.\nQuẻ Cấn: Ngưng nghỉ, mộ, chết chóc.\nQuẻ Lục Xung: Xung tán, chia ly, hoặc xảy ra nhanh.\nCủng cố tư duy: \nPhân tích Vượng/Suy, Nhị Hợp, và ứng kỳ chính xác.\nXử lý quẻ phức tạp: Nhiều hào động, Nhị Hợp, Không Vong.\nNghiệm chứng thực tế: Hành"
