    "summary": "Ứng dụng thực tiễn:\nDự đoán bệnh tật: Vị trí bệnh (dạ dày, mắt, cổ họng, trực tràng), nguyên nhân (ăn uống, bẩm sinh), và thời điểm khỏi.\nNhận diện ung thư qua Câu Trần động/suy.\nXác định bệnh bẩm sinh qua hào 2 (tử cung, bào thai).\nKết hợp phong thủy (hào 1-6 tương ứng cơ thể) để luận bệnh.\nXem tuyển dụng: Đánh giá khả năng thành công qua Quan Quỷ, Thế, và Nhị Hợp.\nÔn tập lý thuyết:\nDụng Thần:\nThế: Bản thân người hỏi.\nQuan Quỷ: Chồng, bệnh đeo thân, lo lắng.\nTử Tôn: Con, cháu, thuốc, đường ruột, mạch máu.\nPhụ Mẫu: Bố mẹ, kính, che chở (tóc, áo ngực).\nThê Tài: Vợ, ăn uống, tiền bạc.\nVượng/Suy:",
    "full_text": "Ví dụ 8: Ngày Dần, tháng Hợi, nam xem tuyển dụng (quẻ Ích biến Hợi).\nỨng dụng thực tiễn: \nDự đoán bệnh tật: Vị trí bệnh (dạ dày, mắt, cổ họng, trực tràng), nguyên nhân (ăn uống, bẩm sinh), và thời điểm khỏi.\nNhận diện ung thư qua Câu Trần động/suy.\nXác định bệnh bẩm sinh qua hào 2 (tử cung, bào thai).\nKết hợp phong thủy (hào 1-6 tương ứng cơ thể) để luận bệnh.\nXem tuyển dụng: Đánh giá khả năng thành công qua Quan Quỷ, Thế, và Nhị Hợp.\nÔn tập lý thuyết: \nDụng Thần: \nThế: Bản thân người hỏi.\nQuan Quỷ: Chồng, bệnh đeo thân, lo lắng.\nTử Tôn: Con, cháu, thuốc, đường ruột, mạch máu.\nPhụ Mẫu: Bố mẹ, kính, che chở (tóc, áo ngực).\nThê Tài: Vợ, ăn uống, tiền bạc.\nVượng/Suy: \nVượng: Được tháng/ngày sinh, Nhị Hợp, Ám Động.\nSuy: Bị tháng/ngày khắc, Nhật/Nguyệt Phá, Không Vong, Nhập Mộ.\nQuá Vượng: Được sinh từ nhiều nguồn (ngày, tháng, hào động, hóa biến) mà không có tiết khí/khắc chế → Bệnh khó chữa, tất phản (quá Vượng thành Suy).\nNhị Hợp: \nTăng lực Vượng, nhưng có thể “tham hợp quên sinh/khắc”.\nHợp tàng khắc: Tý-Sửu, Tỵ-Thân (hợp ban đầu, sau khắc).\nHợp sinh: Ngọ-Mùi, Dần-Hợi (hợp và hỗ trợ).\nỨng kỳ: Giải hợp bằng Xung (ví dụ: Tý-Sửu hợp → Ngọ/Mùi xung).\nỨng kỳ: \nDựa trên Trì/Hợp/Xung, Không Vong, Nguyệt Phá.\nKhông Vong: Ứng khi Xuất Không (ngày/tháng hợp/xung).\nNguyệt Phá: Ứng Trì/Hợp (ví dụ: Tý trong tháng Ngọ → Ứng Tý/Sửu).\nBệnh mới: Quẻ Lục Xung → Khỏi nhanh; Lục Hợp → Kéo dài.\nBệnh lâu: Quẻ Lục Xung → Xấu, khó khỏi; Lục Hợp → Tốt, dễ khỏi.\nVị trí cơ thể (hào 1-6): \nHào 1: Chân, bàn"
