    "full_text": "Ví dụ 23: Ngày Đinh Hợi, tháng Ngọ, bố mẹ xem bệnh cho con gái uống thuốc tự tử (quẻ không rõ).\nỨng dụng thực tiễn: \nDự đoán bệnh tật: Vị trí bệnh (chân, phổi, cổ họng, răng, đường ruột, bộ phận sinh dục), nguyên nhân (ăn uống, tình dục, bẩm sinh), và thời điểm khỏi.\nNhận diện ung thư qua Câu Trần động/suy, Nhật/Nguyệt Phá, và Dụng Thần banh xác.\nXác định bệnh nan y qua tuyệt địa và Nhập Mộ.\nXem phẫu thuật: Bạch Hổ (mổ, máu me), Lục Xung (khỏi nhanh).\nKết hợp phong thủy (hào 1-6 tương ứng cơ thể) để luận bệnh.\nÔn tập lý thuyết: \nDụng Thần: \nThế: Bản thân người hỏi.\nQuan Quỷ: Chồng, bệnh đeo thân, lo lắng.\nTử Tôn: Con, cháu, thuốc, đường ruột, mạch máu.\nPhụ Mẫu: Bố mẹ, kính, che chở (tóc, áo ngực).\nThê Tài: Vợ, ăn uống, tiền bạc.\nỨng: Người không thân thiết.\nVượng/Suy: \nVượng: Được tháng/ngày sinh, Nhị Hợp, Ám Động, phá mộ.\nSuy: Bị tháng/ngày khắc, Nhật/Nguyệt Phá, Không Vong, Nhập Mộ.\nQuá Vượng: Được sinh từ nhiều nguồn mà không có tiết khí/khắc chế → Tất phản (quá Vượng thành Suy).\nNhị Hợp: \nTăng lực Vượng, nhưng có thể “tham hợp quên sinh/khắc”.\nHợp tàng khắc: Tý-Sửu, Tỵ-Thân.\nHợp sinh: Ngọ-Mùi, Dần-Hợi.\nỨng kỳ: Giải hợp bằng Xung (ví dụ: Tý-Sửu → Ngọ/Mùi xung).\nNhật/Nguyệt Phá: \nHào bị ngày/tháng xung → Ứng Trì/Hợp, bệnh đỡ qua tháng phá.\nVí dụ: Tý trong tháng Ngọ → Ứng Tý/Sửu.\nKhông Vong: \nHào Không Vong → Ứng khi Xuất Không (ngày/tháng hợp/xung).\nVí dụ: Tý Không Vong → Ứng Tý (Trì), Ngọ (Xung).\nÁm Động: \nHào Vượng hoặc Không Vong bị ngày/tháng xung.\nVí dụ: Mão Mộc trong"
