    "full_text": "Ví dụ 8: Ngày Bính Tý, tháng Sửu, mất xe (quẻ Ký Tế biến Trấn).\nỨng dụng thực tiễn: \nKiện tụng: \nXem cát hung, kéo dài, thắng/thua.\nDấu hiệu: Phụ Mẫu (đơn kiện, bằng chứng), Quan Quỷ (quan tòa), Thê Tài (lý lẽ), Huynh Đệ (tốn tiền).\nHóa Tuyệt (bằng chứng vô giá trị), Nhị Hợp (kéo dài).\nTù tội: \nDấu hiệu: Tam Hình, Câu Trần, Nhập Mộ, Ẩn Phục tại Hào 2, Tử Tôn khắc, Nhị Hợp.\nDự đoán: Bị bắt, thả ra, thời điểm thả.\nMất xe/vật bị mất: \nDụng Thần: Phụ Mẫu (xe, giấy tờ), Thê Tài (tài sản).\nDấu hiệu: Huynh Đệ động (cướp tài), Hóa Hồi Đầu Khắc, Không Vong, Nhập Mộ.\nDự đoán: Tìm lại được hay không, thời điểm tìm.\nPhong thủy: \nQuẻ Phong Sơn Tiệm: Cầu thang, bàn thờ Thần Tài, tiền bạc.\nQuẻ Phong Hỏa Gia Nhân: Cơi nới, phòng nhỏ.\nQuẻ Khốn vi Khảm: Cây cối, rễ cây, mạch nước ngầm.\nMẹo luận quẻ: \nXe hư (lốp trước, Hào 1, Phụ Mẫu).\nBệnh tật: Hào Tài tổn thương (tốn tiền, đã mua thuốc/đi viện), Tử Tôn động (dùng thuốc).\nÔn tập lý thuyết: \nDụng Thần: \nThế: Người hỏi.\nTử Tôn: Con, cháu, đường, thuốc, rễ cây.\nPhụ Mẫu: Xe, giấy tờ, đơn kiện, bằng chứng, lốp xe.\nThê Tài: Tài sản, ăn uống, lý lẽ.\nQuan Quỷ: Quan tòa, công an, bệnh.\nHuynh Đệ: Bạn bè, cành cây, tốn tiền.\nVượng/Suy: \nVượng: Được tháng/ngày sinh, Nhị Hợp, Ám Động.\nSuy: Bị tháng/ngày khắc, Nhật/Nguyệt Phá, Không Vong, Nhập Mộ.\nQuá Vượng: Tất phản (quá Vượng thành Suy, nguy hiểm).\nNhị Hợp: \nTăng lực Vượng, nhưng có thể “tham hợp quên sinh”.\nỨng kỳ: Giải hợp bằng Xung.\nDấu hiệu tù tội: Bị níu giữ, kéo dài.\nKhông Vong: \nHào Không Vong → Ứn"
