    "hexagrams": [],
    "summary": "Ôn tập: Hào Thai, Tử Tôn, Kim Tượng Hào, Lục Xung/Hợp, Bạch Hổ.\nHướng phát triển:\nHọc quẻ phức tạp (Nhị Hợp, Tam Hợp, Kim Tượng Hào, hóa giải bệnh lý).\nNghiên cứu sinh đẻ, sảy thai qua Lục Hào.\nKết hợp Lục Hào với y tế, phong thủy, chọn thời điểm mổ.\nNghiệm chứng thực tế về thời điểm sinh, giữ thai.\nKhuyến khích:\nThực hành gieo quẻ, kiểm nghiệm thực tế.\nTham gia nhóm học, thảo luận, nghiệm chứng.\nChú ý Tử Tôn, Hào Thai, Kim Tượng Hào, và Bạch Hổ trong luận quẻ sinh đẻ.",
    "full_text": "Ví dụ 12: Sảy thai do vợ có bệnh tử cung, băng huyết (Hào Ứng Lâm Quan Quỷ, Bạch Hổ).\nÔn tập: Hào Thai, Tử Tôn, Kim Tượng Hào, Lục Xung/Hợp, Bạch Hổ.\nHướng phát triển: \nHọc quẻ phức tạp (Nhị Hợp, Tam Hợp, Kim Tượng Hào, hóa giải bệnh lý).\nNghiên cứu sinh đẻ, sảy thai qua Lục Hào.\nKết hợp Lục Hào với y tế, phong thủy, chọn thời điểm mổ.\nNghiệm chứng thực tế về thời điểm sinh, giữ thai.\nKhuyến khích: \nThực hành gieo quẻ, kiểm nghiệm thực tế.\nTham gia nhóm học, thảo luận, nghiệm chứng.\nChú ý Tử Tôn, Hào Thai, Kim Tượng Hào, và Bạch Hổ trong luận quẻ sinh đẻ."
