    "summary": "Ôn tập:\nKhái niệm: Gian Hào, Quái Thân, Hào Thai, Nguyệt Kiến.\nQuy trình luận quẻ: Chọn Dụng Thần, xét Vượng/Suy, phân tích hóa giải.\nỨng dụng: Thai nghén, công danh, phong thủy, tâm linh.\nHướng phát triển\nHọc quẻ phức tạp: Tam Hợp, Nhập Mộ, hóa giải phong thủy.\nNghiên cứu sâu về thai nghén, công danh qua Lục Hào.\nKết hợp Lục Hào với phong thủy, y tế, tâm linh.\nNghiệm chứng thực tế về thời điểm mang thai, thăng chức, hoặc kinh doanh.\nKhuyến khích\nThực hành gieo quẻ, kiểm nghiệm thực tế.\nTham gia nhóm học, thảo luận, nghiệm chứng.\nChú ý Tam Hợp, Nhị Hợp, Không Vong, Hào Thai, Nguyệt Kiến trong luận quẻ.\nGhi chép cẩn thận, kết hợp lý thuyết và thực tiễn.",
    "full_text": "Ví dụ 4 (Hoán biến Khiêm): Không đạt công danh, nhưng bình an nhờ Kim Tượng Hào tốt.\nÔn tập: \nKhái niệm: Gian Hào, Quái Thân, Hào Thai, Nguyệt Kiến.\nQuy trình luận quẻ: Chọn Dụng Thần, xét Vượng/Suy, phân tích hóa giải.\nỨng dụng: Thai nghén, công danh, phong thủy, tâm linh.\nHướng phát triển\nHọc quẻ phức tạp: Tam Hợp, Nhập Mộ, hóa giải phong thủy.\nNghiên cứu sâu về thai nghén, công danh qua Lục Hào.\nKết hợp Lục Hào với phong thủy, y tế, tâm linh.\nNghiệm chứng thực tế về thời điểm mang thai, thăng chức, hoặc kinh doanh.\nKhuyến khích\nThực hành gieo quẻ, kiểm nghiệm thực tế.\nTham gia nhóm học, thảo luận, nghiệm chứng.\nChú ý Tam Hợp, Nhị Hợp, Không Vong, Hào Thai, Nguyệt Kiến trong luận quẻ.\nGhi chép cẩn thận, kết hợp lý thuyết và thực tiễn.\n\nPhương pháp giảng dạy\nKết hợp lý thuyết và thực tiễn: Giảng giải chi tiết các khái niệm, kết hợp phân tích ví dụ thực tế.\nTương tác: Thảo luận, trả lời câu hỏi, kiểm nghiệm quẻ với học viên.\nSử dụng công cụ: Bảng tra cứu (Không Vong, Lục Thú, Trường Sinh), phần mềm gieo quẻ.\nKhuyến khích thực hành: Học viên gieo quẻ, phân tích, ghi chép, nghiệm chứng.\nGiải thích logic: Luận quẻ từng bước, phân tích cát hung và ứng kỳ.\nNgữ cảnh\nBài giảng thuộc khóa nâng cao, tập trung vào quẻ dài, đã nghiệm chứng.\nCác ví dụ thực tế: \nHỏi khi nào có con (quẻ Thủy Thiên Nhu).\nHỏi thăng chức (quẻ Lục Hào, ngày Dậu).\nHỏi sự nghiệp (quẻ Khốn biến Tiểu Súc).\nHỏi công danh (quẻ Hoán biến Khiêm).\nKinh nghiệm giảng viên: \nNghiệm chứng: \nHào Thai xuất hiện ở quẻ biến →"
