    "hexagrams": [],
    "summary": "1. Giới Thiệu Tổng Quan\nMục tiêu bài giảng\nHiểu và áp dụng các khái niệm chuyên sâu trong Kinh Dịch (Lục Hào) để luận quẻ về dự đoán công việc có định hướng (xin việc, phỏng vấn, trúng tuyển) và điều động công việc (thay đổi vị trí, công ty, hoặc thăng chức trong công ty).\nNắm vững quy trình luận quẻ, từ việc chọn Dụng Thần (Quan Quỷ, Phụ Mẫu, Thê Tài, Nguyệt Kiến), xét Vượng/Suy, đến phân tích các yếu tố như Nhị Hợp, Tam Hợp, Không Vong, Nhập Mộ, Hóa Hồi Đầu, và ứng kỳ.\nPhân tích các ví dụ thực tế để kiểm nghiệm tính ứng nghiệm của quẻ, tập trung vào các tình huống như xin việc, phỏng vấn, điều động công việc, thăng chức, hoặc tình hình công ty (khởi động sản xuất, phá sản).\nHướng dẫn cách hóa giải quẻ, bao gồm cải thiện quan hệ với người phỏng vấn, điều chỉnh phong thủy, và xử lý các yếu tố pháp lý hoặc tâm linh.\nGiới thiệu khóa nâng cao\nChủ đề chuyên sâu:\nPhân biệt dự đoán xu thế công việc (dài hạn, không xác định thời gian) và dự đoán công việc có định hướng (ngắn hạn, thời điểm cụ thể).\nVai trò của Nguyệt Kiến trong việc luận công việc có định hướng, đại diện cho người phỏng vấn, lãnh đạo, hoặc cơ quan quyết định.\nPhân tích các quẻ liên quan đến Quan Quỷ Lưỡng Hiện (hai Quan Quỷ) và Phụ Mẫu Lưỡng Hiện (hai Phụ Mẫu), biểu thị thay đổi công việc/công ty.\nỨng dụng Kim Tượng Hào, Hóa Hồi Đầu, và Nhập Mộ để dự đoán cát hung (trúng tuyển, thất bại, thăng chức, mất chức).\nNội dung chính:\nXin việc/phỏng vấn: Dự đoán khả năng trúng tuyển, ấn tượng với người phỏng vấn, và mức lương (Thê Tài).",
