    "full_text": "Ví dụ 7: Quẻ Phong Thiên Tiểu Súc (ngày Ất Tỵ, tháng Tuất) – Hỏi công việc sắp tới.\nVí dụ không số (1): Quẻ có Quan Quỷ và Phụ Mẫu Lưỡng Hiện – Hỏi thi đại học.\nVí dụ không số (2): Quẻ có Quan Quỷ Tỵ Hỏa Lâm Không Vong – Hỏi thi trung học.\nPhương pháp giảng dạy\nLý thuyết kết hợp thực tiễn: \nGiảng giải khái niệm chuyên sâu.\nPhân tích ví dụ thực tế từ file âm thanh.\nThảo luận tương tác với học viên.\nCông cụ hỗ trợ: \nBảng tra cứu Không Vong, Lục Thú, Trường Sinh, Tam Hợp.\nPhần mềm gieo quẻ (nếu cần).\nThực hành: \nHọc viên gieo quẻ, phân tích, và nghiệm chứng.\nKhuyến khích đặt câu hỏi và thảo luận về các trường hợp thực tế.\n2. Các Khái Niệm Chuyên Sâu\n2.1. Nguyệt Kiến trong Dự Đoán Công Việc Có Định Hướng\nĐịnh nghĩa: Nguyệt Kiến là Địa Chi của tháng gieo quẻ, đại diện cho người phỏng vấn, lãnh đạo, hoặc cơ quan quyết định.\nÝ nghĩa: \nChiếm 50% thành bại trong dự đoán ngắn hạn.\nNguyệt Kiến sinh hợp Thế: Lãnh đạo/người phỏng vấn ủng hộ, dễ thành.\nNguyệt Kiến xung khắc Thế: Lãnh đạo không đồng ý, khó thành.\nỨng dụng: \nĐánh giá thái độ của người phỏng vấn/lãnh đạo.\nDự đoán khả năng trúng tuyển, điều động, hoặc thăng chức.\n2.2. Quan Quỷ Lưỡng Hiện\nĐịnh nghĩa: Quẻ có hai Quan Quỷ (tĩnh và động), biểu thị công việc hiện tại và công việc tương lai (tượng Uyên Ương Cầu Sĩ).\nÝ nghĩa: \nQuan Quỷ tĩnh: Công việc hiện tại.\nQuan Quỷ động: Công việc mới, thăng chức, hoặc điều động.\nQuan Quỷ Lâm Không Vong: Công việc hiện tại không thực chất, dễ mất.\nQuan Quỷ hóa Hồi Đầu Khắc, Lâm Ứng: Công việc hi"
