    "full_text": "Ví dụ 3: Quẻ Khôn Tùy (ngày Thân, tháng Tỵ) – Hỏi mở nhà hàng rượu vang cao cấp.\nVí dụ bổ sung: Quẻ có Phụ Mẫu hóa Quan Quỷ – Hỏi về sức khỏe bề trên.\nPhương pháp giảng dạy\nLý thuyết kết hợp thực tiễn: \nGiảng giải khái niệm chuyên sâu (Tam Hình, Dịch Mã, Lục Thú, Kim Tượng Hào).\nPhân tích ví dụ thực tế từ file âm thanh.\nThảo luận tương tác với học viên.\nCông cụ hỗ trợ: \nBảng tra cứu Không Vong, Lục Thú, Tam Hợp, Tam Hình, Dịch Mã.\nPhần mềm gieo quẻ (nếu cần).\nThực hành: \nHọc viên gieo quẻ, phân tích, và nghiệm chứng.\nKhuyến khích đặt câu hỏi và thảo luận về các trường hợp thực tế.\n2. Các Khái Niệm Chuyên Sâu\n2.1. Thê Tài trong Dự Đoán Kinh Doanh\nĐịnh nghĩa: Thê Tài đại diện cho tài lộc, lợi nhuận, nguồn thu nhập, hoặc khả năng kiếm tiền.\nÝ nghĩa: \nThê Tài Vượng: Kinh doanh thuận lợi, lợi nhuận cao, nhiều nguồn thu.\nThê Tài Suy, Không Vong: Tài lộc không thực chất, dễ thua lỗ.\nThê Tài Lâm Không, Ám Động: Có lợi nhuận ngắn hạn, nhưng không bền.\nThê Tài bị Huynh Đệ khắc: Đối thủ cạnh tranh mạnh, tài lộc hao hụt.\nỨng dụng: \nDự đoán hiệu quả kinh doanh, đầu tư.\nXác định thời điểm có lợi nhuận (Xuất Không, Xung Hợp).\n2.2. Tử Tôn trong Kinh Doanh\nĐịnh nghĩa: Tử Tôn đại diện cho nguồn vốn, yếu tố bảo vệ, hoặc cản trở (khắc Quan Quỷ).\nÝ nghĩa: \nTử Tôn Vượng: Nguồn vốn dồi dào, kinh doanh ổn định.\nTử Tôn Suy, Nhập Mộ: Thiếu vốn, khó khởi động kinh doanh.\nTử Tôn khắc Quan Quỷ: Tránh được kiện tụng, bệnh tật, hoặc vong linh quấy nhiễu.\nTử Tôn ẩn phục: Thiếu nguồn vốn, khó giữ tiền.\nỨng d"
