    "full_text": "Bài 34: Luận Quẻ Hợp Tác Cầu Tài, Ký Hợp Đồng, và Bán Xe Ô Tô\n1. Giới Thiệu Tổng Quan\nMục tiêu bài giảng\nHiểu chuyên sâu: Nắm vững cách áp dụng Kinh Dịch (Lục Hào) để dự đoán các vấn đề liên quan đến hợp tác cầu tài, ký hợp đồng, và bán hàng (đặc biệt là bán xe ô tô), bao gồm xác định thái độ hai bên, khả năng thành công, lợi nhuận, tổn hao, và ứng kỳ.\nPhân tích Dụng Thần: \nThê Tài: Đại diện cho tiền bạc, lợi nhuận, hoặc tiềm lực tài chính.\nPhụ Mẫu: Đại diện cho hợp đồng, giấy tờ, hoặc xe ô tô/nhà đất trong bán bất động sản.\nTử Tôn: Đại diện cho khách hàng, nguồn lợi nhuận, hoặc hàng hóa thông thường.\nQuan Quỷ: Đại diện cho công quyền, pháp lý, môi giới, hoặc chi phí bôi trơn.\nHuynh Đệ: Đại diện cho bạn bè, cạnh tranh, hoặc hao tài.\nLuận quẻ nâng cao: Phân tích các yếu tố phức tạp như Thể Ứng Tương Sinh/Khắc, Không Vong, Nhập Mộ, Lục Hợp, Tam Hình, Hóa Hồi Đầu, và Lục Thú (Thanh Long, Đằng Xà, Huyền Vũ, Bạch Hổ) để đưa ra dự đoán chính xác về cát hung và ứng kỳ.\nỨng dụng thực tế: Thông qua các ví dụ từ file (quẻ Bác Tốn, Tỷ, Vô Vọng, Hoán, Chấn, Thuần Càn Lục Xung), học viên sẽ học cách luận quẻ, nghiệm chứng, và hóa giải để tối ưu hóa kết quả.\nKỹ năng thực hành: Khuyến khích học viên tự gieo quẻ, phân tích, và áp dụng vào các tình huống thực tế như hợp tác làm ăn, ký hợp đồng, hoặc bán hàng.\nNội dung chính\nDự đoán hợp tác cầu tài: \nThể Ứng: Xác định thái độ và thực lực của hai bên (Thế: bản thân; Ứng: đối phương).\nThê Tài: Đánh giá tiềm lực tài chính và lợi nhuận.\nPhụ Mẫu: X"
