    "hexagrams": [],
    "summary": "1. Giới Thiệu Tổng Quan\nMục tiêu bài giảng\nHiểu chuyên sâu: Nắm vững cách áp dụng Kinh Dịch (Lục Hào) để dự đoán các vấn đề liên quan đến việc tìm người mất tích, bao gồm xác định vị trí, tình trạng (bình an hay nguy hiểm), thời điểm tìm được, và các yếu tố ảnh hưởng.\nPhân tích Dụng Thần:\nTử Tôn: Đại diện cho con cái, người trẻ tuổi, hoặc người cần tìm (thường dùng khi tìm con cái).\nQuan Quỷ: Đại diện cho chồng, bạn trai, hoặc người có vai vế (dùng khi tìm chồng, bạn trai, hoặc người lớn tuổi).\nHuynh Đệ: Đại diện cho anh chị em, bạn bè, hoặc người đồng vai vế (dùng khi tìm anh chị em, bạn bè).\nPhụ Mẫu: Đại diện cho tin tức, giấy tờ, hoặc nơi ở (nhà cửa, khách sạn).\nLuận quẻ nâng cao: Phân tích các yếu tố phức tạp như Thể Ứng Tương Sinh/Khắc, Không Vong, Nhập Mộ, Lục Hợp, Nhị Hợp, Tam Hình, Hóa Hồi Đầu, Lục Thú (Thanh Long, Chu Tước, Huyền Vũ, Bạch Hổ), Trường Sinh, Mộc Dục, Ám Động, Duy Thành Phẩm, và Kim Tượng Hào để đưa ra dự đoán chính xác về vị trí, tình trạng, và thời điểm tìm được.\nỨng dụng thực tế: Thông qua các ví dụ từ file (ví dụ 1: ngày Giáp Dần, tháng Thân; ví dụ 2: ngày Kỷ Mão, tháng Mão; ví dụ 3: ngày Ất Dậu, tháng Thìn; ví dụ 4: ngày Ất Dậu, tháng Dần; ví dụ 5: ngày Ngọ, tháng Mùi; ví dụ 6: ngày Tý, tháng Sửu), học viên sẽ học cách luận quẻ, nghiệm chứng, và đề xuất phương pháp tìm kiếm hoặc hóa giải khi quẻ báo hung.\nKỹ năng thực hành: Khuyến khích học viên tự gieo quẻ, phân tích, và áp dụng vào các tình huống thực tế như tìm con cái, anh chị em, hoặc người mất tích nói chung.\nNội dung chính\nDự đoán tìm người mất tích:\nDụng Thần:",
    "full_text": "Bài 37: Luận Quẻ Tìm Người Mất Tích (Vị Trí, Tình Trạng, Ứng Kỳ)\n1. Giới Thiệu Tổng Quan\nMục tiêu bài giảng\nHiểu chuyên sâu: Nắm vững cách áp dụng Kinh Dịch (Lục Hào) để dự đoán các vấn đề liên quan đến việc tìm người mất tích, bao gồm xác định vị trí, tình trạng (bình an hay nguy hiểm), thời điểm tìm được, và các yếu tố ảnh hưởng.\nPhân tích Dụng Thần: \nTử Tôn: Đại diện cho con cái, người trẻ tuổi, hoặc người cần tìm (thường dùng khi tìm con cái).\nQuan Quỷ: Đại diện cho chồng, bạn trai, hoặc người có vai vế (dùng khi tìm chồng, bạn trai, hoặc người lớn tuổi).\nHuynh Đệ: Đại diện cho anh chị em, bạn bè, hoặc người đồng vai vế (dùng khi tìm anh chị em, bạn bè).\nPhụ Mẫu: Đại diện cho tin tức, giấy tờ, hoặc nơi ở (nhà cửa, khách sạn).\nLuận quẻ nâng cao: Phân tích các yếu tố phức tạp như Thể Ứng Tương Sinh/Khắc, Không Vong, Nhập Mộ, Lục Hợp, Nhị Hợp, Tam Hình, Hóa Hồi Đầu, Lục Thú (Thanh Long, Chu Tước, Huyền Vũ, Bạch Hổ), Trường Sinh, Mộc Dục, Ám Động, Duy Thành Phẩm, và Kim Tượng Hào để đưa ra dự đoán chính xác về vị trí, tình trạng, và thời điểm tìm được.\nỨng dụng thực tế: Thông qua các ví dụ từ file (ví dụ 1: ngày Giáp Dần, tháng Thân; ví dụ 2: ngày Kỷ Mão, tháng Mão; ví dụ 3: ngày Ất Dậu, tháng Thìn; ví dụ 4: ngày Ất Dậu, tháng Dần; ví dụ 5: ngày Ngọ, tháng Mùi; ví dụ 6: ngày Tý, tháng Sửu), học viên sẽ học cách luận quẻ, nghiệm chứng, và đề xuất phương pháp tìm kiếm hoặc hóa giải khi quẻ báo hung.\nKỹ năng thực hành: Khuyến khích học viên tự gieo quẻ, phân tích, và áp dụng vào"
