    "hexagrams": [],
    "summary": "1. Giới Thiệu Tổng Quan\nMục tiêu bài giảng\nHiểu chuyên sâu: Nắm vững cách áp dụng Kinh Dịch (Lục Hào) để dự đoán bệnh tật, bao gồm xác định bệnh lý, vị trí bệnh, mức độ nghiêm trọng, khả năng chữa trị, và thời điểm nguy hiểm (ứng kỳ).\nPhân tích các yếu tố chính:\nDụng Thần: Đại diện cho người bệnh hoặc bộ phận cơ thể (Thê Tài - tiêu hóa, Tử Tôn - sinh dục, Phụ Mẫu - lồng ngực, Quan Quỷ - bệnh tật).\nNguyên Thần: Đại diện cho sức khỏe, cần Vượng để hỗ trợ Dụng Thần.\nKỳ Thần/Cừu Thần: Đại diện cho bệnh tật, khắc Dụng Thần/Nguyên Thần.\nBệnh Địa/Tử Địa: Giai đoạn bệnh và tử trong vòng Trường Sinh, xác định mức độ nguy hiểm.\nLục Thú: Thanh Long (thuốc Đông y, ẩm thực), Chu Tước (viêm), Câu Trần (khối u, sưng trướng), Bạch Hổ (mổ sẻ, máu me), Huyền Vũ (nước, dịch), Đằng Xà (mạch máu, dây thần kinh).\nNhật Nguyệt: Ảnh hưởng Vượng/Suy, nhập quẻ làm bệnh.\nKhông Vong/Nhập Mộ: Biểu thị bệnh ẩn, khó chữa, hoặc mất đi.\nLục Hợp/Nhị Hợp: Tăng cường lực, nhưng có thể biểu thị bệnh bị kìm hãm.\nHóa Thoái/Phá/Không: Biểu thị bệnh suy giảm, cắt bỏ, hoặc mất đi.\nPhục Tàng/Ám Động: Bệnh ẩn, hành động ngầm.",
    "full_text": "Bài 39: Luận Quẻ Sức Khỏe và Bệnh Tật (Chuyên Sâu)\n1. Giới Thiệu Tổng Quan\nMục tiêu bài giảng\nHiểu chuyên sâu: Nắm vững cách áp dụng Kinh Dịch (Lục Hào) để dự đoán bệnh tật, bao gồm xác định bệnh lý, vị trí bệnh, mức độ nghiêm trọng, khả năng chữa trị, và thời điểm nguy hiểm (ứng kỳ).\nPhân tích các yếu tố chính: \nDụng Thần: Đại diện cho người bệnh hoặc bộ phận cơ thể (Thê Tài - tiêu hóa, Tử Tôn - sinh dục, Phụ Mẫu - lồng ngực, Quan Quỷ - bệnh tật).\nNguyên Thần: Đại diện cho sức khỏe, cần Vượng để hỗ trợ Dụng Thần.\nKỳ Thần/Cừu Thần: Đại diện cho bệnh tật, khắc Dụng Thần/Nguyên Thần.\nBệnh Địa/Tử Địa: Giai đoạn bệnh và tử trong vòng Trường Sinh, xác định mức độ nguy hiểm.\nLục Thú: Thanh Long (thuốc Đông y, ẩm thực), Chu Tước (viêm), Câu Trần (khối u, sưng trướng), Bạch Hổ (mổ sẻ, máu me), Huyền Vũ (nước, dịch), Đằng Xà (mạch máu, dây thần kinh).\nNhật Nguyệt: Ảnh hưởng Vượng/Suy, nhập quẻ làm bệnh.\nKhông Vong/Nhập Mộ: Biểu thị bệnh ẩn, khó chữa, hoặc mất đi.\nLục Hợp/Nhị Hợp: Tăng cường lực, nhưng có thể biểu thị bệnh bị kìm hãm.\nHóa Thoái/Phá/Không: Biểu thị bệnh suy giảm, cắt bỏ, hoặc mất đi.\nPhục Tàng/Ám Động: Bệnh ẩn, hành động ngầm.\nTượng Quẻ: Biểu thị tình trạng bệnh (Ly - xa đường, Vô Vọng - nguy hiểm).\nLuận quẻ nâng cao: Phân tích 24 trường hợp luận bệnh từ file, bao gồm các trường hợp phức tạp như Dụng Thần/Nguyên Thần gặp Bệnh Địa/Tử Địa, Quan Quỷ/Kỳ Thần động, và Nhị Hợp hóa ngũ hành.\nỨng dụng thực tế: Thông qua các ví dụ từ file (ví dụ 1: bệnh não trẻ em; ví dụ 2: cảm"
