    "full_text": "Bài 42: Luận Quẻ Bán Đất, Nhà Cửa và Các Vấn Đề Bệnh Tật Liên Quan\n1. Giới Thiệu Tổng Quan\nMục tiêu bài giảng\nHiểu chuyên sâu: Nắm vững cách áp dụng Kinh Dịch (Lục Hào) để dự đoán các vấn đề liên quan đến bán đất, nhà cửa, phong thủy, và bệnh tật, bao gồm xác định khả năng bán đất, giá cả, thời điểm bán, vấn đề phong thủy, và tình trạng bệnh lý.\nPhân tích các yếu tố chính: \nDụng Thần: \nPhụ Mẫu: Giấy tờ, sổ đỏ, văn bản hợp đồng.\nThê Tài: Tiền bạc, giá bán, lý lẽ.\nTử Tôn: Con đường, chợ, chùa, công an, trẻ em.\nQuan Quỷ: Quan tòa, công quyền, bệnh tật, vấn đề pháp lý.\nHuynh Đệ: Bạn bè, hàng xóm, môi giới, tranh chấp.\nNguyên Thần: Hỗ trợ Dụng Thần, cần Vượng để tăng khả năng bán đất hoặc chữa bệnh.\nKỳ Thần/Cừu Thần: Khắc Dụng Thần/Nguyên Thần, biểu thị khó khăn, đối thủ, hoặc bệnh nặng.\nNhàn Thần: Không sinh, không khắc Dụng Thần, có thể gây trở ngại nếu Vượng.\nTiết Thần: Làm tiết khí Dụng Thần, thường xếp vào Nhàn Thần.\nLục Thú: \nThanh Long: Hợp đồng, văn bản, cây cối, sự thuận lợi.\nChu Tước: Tranh cãi, miệng lưỡi, tụng kinh, chợ búa.\nCâu Trần: Khối kiến trúc, mộ phần, tắc nghẽn, ung thư.\nBạch Hổ: Con đường, cầu, bệnh nặng, tử hình, đổ máu.\nHuyền Vũ: Mờ ám, lừa đảo, nước, bệnh thiếu oxy.\nĐằng Xà: Trói buộc, liên lụy, con đường, bệnh mãn tính.\nNhật Nguyệt: \nSinh Dụng Thần: Dễ bán đất, bệnh nhẹ.\nKhắc Dụng Thần: Khó bán, bệnh nặng.\nNhập quẻ: Làm kiện hoặc kích hoạt sự việc nếu trùng ngũ hành.\nKhông Vong: \nDụng Thần không vong: Giấy tờ ẩn, bệnh ẩn, khó bán.\nKỳ Thần không vong: Đối t"
