    "full_text": "Bài 45: Quẻ Trạch Hỏa Cách, Phong Hỏa Phong và Khái Niệm Cách Sơn Hóa Hào\n1. Giới Thiệu Tổng Quan\nMục tiêu bài giảng\nHiểu chuyên sâu: Nắm vững cách phân tích quẻ Trạch Hỏa Cách, Phong Hỏa Phong, và khái niệm Cách Sơn Hóa Hào. Ứng dụng các quẻ này trong dự đoán tài vận, phong thủy, sức khỏe, công việc, và tâm linh.\nPhân tích các yếu tố chính: \nQuẻ Trạch Hỏa Cách: \nBiểu thị sự cách trở, đổi mới, cải cách, mâu thuẫn giữa tư tưởng cũ và mới.\nHào 5 động: Nhân sự (cô giáo, nhân viên) thay đổi, nghỉ việc.\nTâm linh: Đổi bài vị, kiểm tra bàn thờ.\nQuẻ Phong Hỏa Phong: \nBiểu thị tiếng động (sấm sét) trên lửa, liên quan đến thị phi, tranh cãi.\nCúng lễ: Dùng 5 cây nhang, kiểm tra hỏa khí.\nCách Sơn Hóa Hào: \nHào động liên tục tạo chuỗi biến hóa (Tý → Sửu → Dậu → Tỵ).\nỨng dụng: Dự đoán tài vận, sự kiện phức tạp.\nThần Sát: \nBạch Hổ: Cơ quan chức năng, bệnh nặng, kim khí, tai nạn.\nChu Tước: Tranh cãi, tin tức, thị phi.\nHuyền Vũ: Mờ ám, lừa gạt, trộm cắp.\nThanh Long: Văn thư, trẻ nhỏ, ngây thơ.\nCâu Trần: Đất thổ, thật thà, khối kiến trúc.\nĐằng Xà: Trói buộc, bệnh tật, thị phi.\nNhật/Nguyệt Thần: \nNhật Thần: Tác động mạnh đến Vượng/Suy.\nNguyệt Thần: Hỗ trợ hoặc khắc chế.\nNhị Hợp/Tam Hình: \nNhị Hợp: Quan hệ thân thiết, lăng nhăng.\nTam Hình (Sửu-Mùi-Tuất, Dần-Tỵ-Thân): Xung khắc, mất mát, sảy thai.\nỨng dụng thực tế: \nDự đoán tài vận, công việc, sức khỏe, phong thủy, tâm linh.\nXác định mâu thuẫn nhân sự, lừa gạt, thị phi.\nLuận vận hạn cá nhân hoặc gia đình.\nKỹ năng thực hành: \nGieo quẻ và luận dựa"
