    "full_text": "Bài 48: Luận Quẻ Kiện Tụng (Bất Động Sản, Tai Nạn Giao Thông, Tình Hình Công Ty)\n1. Giới Thiệu Tổng Quan\nMục tiêu bài giảng\nHiểu chuyên sâu: Nắm vững cách phân tích quẻ trong các tình huống thực tế như bất động sản, kiện tụng, tai nạn giao thông, và tình hình công ty.\nPhân tích các yếu tố chính: \nBất động sản: \nDự đoán thời điểm đầu tư, giá trị đất, và người đỡ đầu.\nThê Tài, Lộc Tồn, Câu Trần: Tài lộc, đất đai.\nKiện tụng: \nXác định tình trạng bị bắt, khả năng được thả, và thế lực cứu trợ.\nQuan Quỷ, Phụ Mẫu, Thần Sát (Thiên Xá, Hoàng Ân): Quan tòa, đơn kiện, giảm nhẹ tội.\nTai nạn giao thông: \nXác định trách nhiệm, tình trạng nạn nhân, và hậu quả pháp lý.\nQuan Quỷ, Huynh Đệ, Thê Tài: Cơ quan thẩm quyền, anh em, tài sản.\nTình hình công ty: \nDự đoán hoạt động kinh doanh, hỗ trợ từ chính quyền, và tranh chấp tài chính.\nPhụ Mẫu, Thê Tài, Quan Quỷ: Công ty, tài chính, nhà nước.\nThần Sát: \nThiên Xá, Hoàng Ân: Giảm nhẹ kiện tụng.\nChu Tước: Tin tức, tranh cãi, vợ trước.\nCâu Trần: Nhà cửa, đất đai, móc nối.\nĐằng Xà: Lo âu, dây trói, mộng mị.\nThanh Long: Nhà nước, tài lộc.\nNhị Hợp/Tam Hợp: \nNhị Hợp: Quan hệ thân thiết, ngoại tình.\nTam Hợp: Thân-Tý-Thìn, hỗ trợ sự việc.\nDịch Mã: Di chuyển, thay đổi.\nLộc Tồn: Tài lộc dồi dào.\nTrường Sinh: Khởi đầu mới, cứu trợ.\nỨng dụng thực tế: \nDự đoán thời điểm và kết quả đầu tư bất động sản.\nLuận kiện tụng: Ai bị bắt, ai cứu, khi nào thả.\nPhân tích tai nạn: Trách nhiệm, hậu quả, hóa giải.\nĐánh giá công ty: Tình hình kinh doanh, hỗ trợ, tranh chấp.\nKỹ n"
