    "full_text": "Bài 49: Luận Quẻ Điều Tra Học Thuật và Kiện Tụng (Tình Trạng Người Thân)\n1. Giới Thiệu Tổng Quan\nMục tiêu bài giảng\nHiểu chuyên sâu: Nắm vững cách phân tích quẻ trong các tình huống thực tế như điều tra học thuật, kiện tụng, và tình trạng người thân bị kiện.\nPhân tích các yếu tố chính: \nĐiều tra tốt nghiệp sinh viên: \nDự đoán khả năng hoàn thành cuộc điều tra.\nDụng Thần: Phụ Mẫu (giấy tờ, điều tra).\nThần Sát: Chu Tước (tin tức), Huyền Vũ (ngục tối, mờ mịt).\nKiện tụng: \nXác định tình trạng bị kiện, khả năng thoát tội, và mức độ nghiêm trọng.\nDụng Thần: Huynh Đệ (người hỏi), Quan Quỷ (vụ án, công an).\nThần Sát: Bạch Hổ (tự hình, án nặng), Thiên Xá (giảm nhẹ).\nTình trạng người thân: \nDự đoán tình trạng con cái hoặc chồng bị kiện, khả năng thoát tù.\nDụng Thần: Tử Tôn (con cái), Quan Quỷ (chồng, vụ án).\nThần Sát: Huyền Vũ (ngục tối), Thanh Long (nhà nước, cứu trợ).\nThần Sát: \nChu Tước: Tin tức, tranh cãi, bản án.\nHuyền Vũ: Ngục tối, ma túy, mờ mịt.\nBạch Hổ: Tự hình, án nặng.\nThanh Long: Nhà nước, tài lộc, cứu trợ.\nĐằng Xà: Lo âu, dây trói, ma túy.\nNhị Hợp/Tam Hợp: \nNhị Hợp: Tý-Ngọ, Sửu-Mùi, quan hệ thân thiết, giam giữ.\nTam Hợp: Thân-Tý-Thìn, hỗ trợ sự việc.\nDịch Mã: Di chuyển, thay đổi, đi xa.\nTrường Sinh: Khởi đầu mới, học hành, cứu trợ.\nTam Hình: Tý-Mão, Dần-Tỵ-Thân, biểu thị tù tội, hình ngục.\nỨng dụng thực tế: \nDự đoán khả năng hoàn thành điều tra học thuật.\nLuận kiện tụng: Ai bị bắt, ai cứu, mức độ án.\nĐánh giá tình trạng người thân: Tù tội, thoát tù, thời gian giam giữ.\nKỹ"
