    "full_text": "Bài 51: Luận Quẻ Bệnh Tật (Rối Loạn Kinh Nguyệt, U Sơ, Ảo Giác) và Khả Năng Sinh Con\n1. Giới Thiệu Tổng Quan\nMục tiêu bài giảng\nHiểu chuyên sâu: Nắm vững cách phân tích quẻ trong dự đoán bệnh tật và khả năng sinh con, với các tình huống thực tế như bệnh của vợ (rối loạn kinh nguyệt, đau thắt lưng, u sơ), bệnh của bản thân (ảo giác, phong thủy), và khả năng sinh con (tinh trùng yếu).\nPhân tích các yếu tố chính: \nBệnh tật: \nDự đoán bệnh lý, nguyên nhân, và khả năng hồi phục.\nDụng Thần: \nThê Tài: Vợ, huyết dịch, ăn uống, kinh nguyệt.\nThế: Bản thân, tâm trí.\nTử Tôn: Con cái, thuốc, sinh dục.\nThần Sát: \nChu Tước: Viêm, nói năng linh tinh.\nBạch Hổ: Máu huyết, ngũ quan (mũi, miệng), đường đi.\nHuyền Vũ: Mờ ám, bệnh không rõ nguyên nhân, âm khí.\nĐằng Xà: Lo âu, ảo giác, sưng trướng, khói/mây.\nThanh Long: Đau nhức, chơi bời, tửu sắc.\nCâu Trần: Khối kiến trúc, sưng trướng, sửa chữa.\nNgũ Hành và Lục Thân: \nQuan Quỷ: Bệnh tật, lo âu, gan.\nPhụ Mẫu: Nhà cửa, giấy tờ, bệnh do mệt nhọc, phong thủy.\nHuynh Đệ: Chân tay, tiêu hóa, tranh cãi.\nTử Tôn: Thuốc, cứu trợ, sinh dục.\nThê Tài: Ăn uống, huyết dịch, kinh nguyệt, tinh dịch.\nVòng Trường Sinh: \nXác định bệnh địa (xung với Trường Sinh) và tử địa (xung với bệnh địa).\nVí dụ: Dần Mộc, Trường Sinh tại Hợi, bệnh tại Tỵ, tử tại Ngọ.\nNhật Phá/Nguyệt Phá: \nNhật Phá: Hào bị Nhật khắc hoặc xung.\nNguyệt Phá: Hào bị Nguyệt khắc hoặc xung.\nNhập Mộ: \nHào hoặc Dụng Thần lâm Mộ (Tuất, Sửu, Thìn, Mùi) và bị Nhật/Nguyệt khắc: Bệnh nặng, nguy kịch.\nKhông Vong: \nH"
