    "full_text": "Bài 52: Luận Quẻ Bệnh Tật (Tai Nạn, Dạ Dày, Bệnh Cũ) và Hóa Giải\n1. Giới Thiệu Tổng Quan\nMục tiêu bài giảng\nHiểu chuyên sâu: Nắm vững cách phân tích quẻ trong dự đoán bệnh tật (bệnh của cha, bệnh dạ dày) và nhân duyên (ngoại tình, quan hệ tình cảm), với các ví dụ thực tế.\nPhân tích các yếu tố chính: \nBệnh tật: \nDự đoán bệnh lý, nguyên nhân, và khả năng hồi phục.\nDụng Thần: \nPhụ Mẫu: Cha mẹ, xe cộ, phong thủy.\nThế: Bản thân, tâm trí.\nTử Tôn: Thuốc, bác sĩ, sinh dục.\nThần Sát: \nBạch Hổ: Máu huyết, ngũ quan, tử vong, đường đi.\nCâu Trần: Xưng trướng, bệnh cũ, sửa chữa.\nĐằng Xà: Lo âu, bất an, che giấu.\nHuyền Vũ: Âm khí, bệnh mờ ám.\nNgũ Hành và Lục Thân: \nQuan Quỷ: Bệnh tật, lo âu, gan.\nPhụ Mẫu: Xe cộ, nhà cửa, bệnh do phong thủy.\nHuynh Đệ: Chân tay, tiêu hóa.\nTử Tôn: Thuốc, bác sĩ, sinh dục.\nThê Tài: Ăn uống, huyết dịch.\nVòng Trường Sinh: \nXác định bệnh địa (xung với Trường Sinh) và tử địa (xung với bệnh địa).\nVí dụ: Hợi Thủy, Trường Sinh tại Thân, bệnh tại Dần, tử tại Mão.\nNhật Phá/Nguyệt Phá: \nNhật Phá: Hào bị Nhật khắc hoặc xung.\nNguyệt Phá: Hào bị Nguyệt khắc hoặc xung.\nNhập Mộ: \nHào hoặc Dụng Thần lâm Mộ (Tuất, Sửu, Thìn, Mùi) và bị Nhật/Nguyệt khắc: Bệnh nặng, nguy kịch.\nKhông Vong: \nHào hoặc Dụng Thần lâm Không Vong: Bệnh yếu, không rõ nguyên nhân, ngủ không yên.\nNhị Hợp: \nTý-Sửu, Dần-Hợi: Hỗ trợ cứu trợ hoặc giam giữ bệnh.\nPhong thủy: \nHào 1: Nền nhà.\nHào 2: Nhà cửa, bệnh do phong thủy.\nHào 3: Cửa, đường đi, dạ dày.\nHào 5: Ngũ quan, đường đi.\nHào 6: Mộ phần, chùa/miếu.\nNh"
