    "full_text": "Bài 56: Luận Quẻ Tìm Người, Tìm Vật và Các Vấn Đề Tâm Linh\n1. Giới Thiệu Tổng Quan\nMục tiêu bài giảng\nHiểu chuyên sâu: \nNắm vững cách phân tích quẻ Lục Hào trong các tình huống tìm người (con cái bỏ nhà, mất tích), tìm vật (mất tiền, mất xe), và các trường hợp liên quan đến tâm linh (ma quỷ, ảo giác).\nỨng dụng các yếu tố như Dụng Thần, Thần Sát, Nhị Hợp, Tam Hợp, Không Vong, Nhập Mộ, Phục Thần để luận chính xác.\nPhân tích các yếu tố chính: \nTìm người/tìm vật: \nDụng Thần: \nQuan Quỷ: Người mất tích, trộm cắp, tâm linh (ma quỷ).\nThê Tài: Tiền bạc, tài sản.\nPhụ Mẫu: Giấy tờ, phương tiện (xe cộ, điện thoại).\nTử Tôn: Manh mối, công an, phúc đức, con cái.\nHuynh Đệ: Đối thủ, người cản trở.\nThế: Bản thân người hỏi.\nỨng: Nơi xảy ra sự việc, hướng tìm kiếm.\nThần Sát: \nThanh Long: Nhà nước, nước, vui chơi.\nCâu Trần: Mộ, đất có vong, u ám.\nĐằng Xà: Ảo giác, mơ hồ, dây điện, ma quỷ.\nHuyền Vũ: Âm muội, trộm cắp, nước, tâm linh.\nChu Tước: Tin tức, văn thư, phía trước.\nBạch Hổ: Hung họa, bệnh tật, xương cốt.\nNhị Hợp: \nTý-Sửu, Dần-Hợi, Mão-Tuất, Thìn-Dậu, Tỵ-Ngọ, Thân-Mùi.\nDụng Thần Nhị Hợp với hào khác: Người/vật bị dẫn dụ, móc nối.\nTam Hợp/Tam Hội: \nTam Hợp: Thân-Tý-Thìn (Thủy), Dần-Ngọ-Tuất (Hỏa), Hợi-Mão-Mùi (Mộc), Tỵ-Dậu-Sửu (Kim).\nTam Hội: \nDần-Mão-Thìn: Đồng hương.\nTỵ-Ngọ-Mùi: Cùng chí hướng.\nThân-Dậu-Tuất: Bạn học, đồng nghiệp.\nHợi-Tý-Sửu: Đồng chí.\nTam Hợp ở Quan Quỷ/Phụ Mẫu: Người mất tích đi với bạn bè, đồng nghiệp.\nKhông Vong: \nDụng Thần lâm Không Vong: Không manh mối, khó tìm.\nTử"
