    "full_text": "Bài 59: Luận Quẻ Gia Đạo và Lý Thuyết Phong Thủy Gia Trạch (Tổng Hợp)\n1. Giới Thiệu Tổng Quan\nMục tiêu bài giảng\nHiểu chuyên sâu: \nNắm vững cách phân tích quẻ Lục Hào trong các tình huống thực tế: xem phong thủy gia trạch, xác định vấn đề tâm linh (vong đói, vong theo con), tài chính (bất động sản bị kẹt), và sức khỏe (bệnh tật gia đình).\nỨng dụng các yếu tố như Dụng Thần, Thần Sát, Nhị Hợp, Tam Hợp, Không Vong, Nhập Mộ, Phục Thần để luận chính xác.\nPhân tích các yếu tố chính: \nDụng Thần: \nQuan Quỷ: Vong, ma quỷ, bệnh tật, kiện tụng.\nThê Tài: Tiền bạc, tài sản, vợ, bồ.\nPhụ Mẫu: Nhà cửa, giấy tờ, bố mẹ, phần mộ.\nTử Tôn: Con cái, phúc đức, phòng ngủ, chùa miếu.\nHuynh Đệ: Anh em, đồng nghiệp, mâu thuẫn.\nThế: Bản thân người hỏi.\nỨng: Đối phương, vợ/chồng, vị trí bên ngoài.\nThần Sát: \nThanh Long: Bên trái nhà, nước, sắc dục, danh gia vọng tộc.\nBạch Hổ: Bên phải nhà, hung họa, bệnh tật, máu huyết.\nHuyền Vũ: Phía sau nhà, nước, tâm linh, nhà vệ sinh.\nChu Tước: Phía trước nhà, tin tức, cãi nhau, bàn thờ.\nĐằng Xà: Giữa nhà, lo lắng, ma quỷ, dây điện.\nCâu Trần: Mộ, tổ tiên, công trình kiến trúc.\nNhị Hợp: \nTý-Sửu, Dần-Hợi, Mão-Tuất, Thìn-Dậu, Tỵ-Ngọ, Thân-Mùi.\nDụng Thần Nhị Hợp với hào khác: Ràng buộc, dẫn dụ, hòa hợp.\nTam Hợp/Tam Hội: \nTam Hợp: Thân-Tý-Thìn (Thủy), Dần-Ngọ-Tuất (Hỏa), Hợi-Mão-Mùi (Mộc), Tỵ-Dậu-Sửu (Kim).\nTam Hội: \nDần-Mão-Thìn: Đồng hương.\nTỵ-Ngọ-Mùi: Cùng chí hướng.\nThân-Dậu-Tuất: Bạn học, đồng nghiệp.\nHợi-Tý-Sửu: Đồng chí.\nDụng Thần lâm Tam Hợp/Tam Hội: Liên quan đến"
