    "full_text": "Bài 60: Luận Quẻ Phong Thủy Gia Trạch, Tâm Linh và Âm Quý Nhân\n1. Giới Thiệu Tổng Quan\nMục tiêu bài giảng\nHiểu chuyên sâu: \nNắm vững cách phân tích quẻ Lục Hào trong các tình huống thực tế: phong thủy gia trạch (xây sửa nhà, đất đai), tâm linh (vong, thờ cúng), tài chính (bán nhà, vay nợ), sức khỏe (bệnh tật), và kiện tụng (tranh chấp đất đai).\nỨng dụng các yếu tố như Dụng Thần, Thần Sát (Thanh Long, Chu Tước, Đằng Xà, Huyền Vũ, Bạch Hổ, Câu Trần), Nhị Hợp, Tam Hợp, Không Vong, Nhập Mộ, Phục Thần để luận chính xác.\nPhân tích các yếu tố chính: \nDụng Thần: \nQuan Quỷ: Vong, bệnh tật, kiện tụng, sếp, chồng.\nThê Tài: Tiền bạc, vợ, chợ, ăn uống.\nPhụ Mẫu: Nhà cửa, giấy tờ, bố mẹ, phần mộ.\nTử Tôn: Con cái, phúc đức, bàn thờ, chùa miếu.\nHuynh Đệ: Anh em, bạn bè, đồng nghiệp, thị phi.\nThế: Bản thân người hỏi.\nỨng: Đối phương, hàng xóm, khách hàng.\nThần Sát: \nThanh Long: Bên trái nhà, nước, danh gia, sắc dục, tin vui (hôn nhân, thăng quan, sinh con).\nChu Tước: Phía trước nhà, tin tức, thị phi, kiện tụng, bàn thờ, hỏa hoạn.\nĐằng Xà: Giữa nhà, lo lắng, ma quỷ, dây trói buộc, mộng mị.\nHuyền Vũ: Phía sau nhà, nước, tâm linh, đạo tặc, nhà vệ sinh.\nBạch Hổ: Bên phải nhà, hung họa, bệnh tật, máu huyết, tai nạn.\nCâu Trần: Mộ, tổ tiên, công trình kiến trúc, đất đai rộng.\nNhị Hợp: \nTý-Sửu, Dần-Hợi, Mão-Tuất, Thìn-Dậu, Tỵ-Ngọ, Thân-Mùi.\nDụng Thần Nhị Hợp: Ràng buộc, dẫn dụ, hòa hợp.\nTam Hợp/Tam Hội: \nTam Hợp: Thân-Tý-Thìn (Thủy), Dần-Ngọ-Tuất (Hỏa), Hợi-Mão-Mùi (Mộc), Tỵ-Dậu-Sửu (Kim).\nTam Hội: \nD"
