    "summary": "Quẻ gốc: Nhu biến Tỉnh.\nHào động: Hào sơ (Tý Thủy).\nPhân tích:\nHào sơ (Tý Thủy): Lâm thê tài, biểu thị nền nhà có giếng hoặc nước ngầm. Biến thành Sửu Thổ (mộ của Kim), nên giếng đã bị lấp bằng tấm đan bê tông.\nQuẻ ngoại (Khảm): Biểu thị nước ở phía Bắc, tức giếng nằm ở phía sau nhà.\nHào hai (Dần Mộc, Chu Tước): Biểu thị cây to trước nhà, bên trái. Do lâm không, cây đã bị chặt (vì gốc cây không còn).\nKết luận:\nNgôi nhà hướng Nam, giếng nằm ở phía sau nhà, đã bị lấp. Trước đây có cây to ở sân trước, bên trái, và một cây nhỏ bên phải (cây cóc, ăn quả được). Cây đã bị chặt vào khoảng năm 1994-1995.\nPhản hồi thực tế: Gia chủ xác nhận giếng sâu khoảng 10m, đã lấp bằng tấm đan. Cây to có đường kính 25cm, cây cóc cho trái ngon nhưng không có hạt.",
