    "full_text": "Quẻ 1: Quẻ Thiên Địa Bĩ biến Lôi Địa Dự\nThông tin quẻ: \nNgày: Không rõ cụ thể.\nQuẻ gốc: Thiên Địa Bĩ (thế khắc ứng, biểu thị khó khăn ban đầu).\nQuẻ biến: Lôi Địa Dự (thế và ứng đồng hành, biểu thị thuận lợi về sau).\nHào động: Không rõ cụ thể, nhưng phân tích dựa trên các hào và ngũ hành.\nPhân tích: \nQuẻ gốc (Thiên Địa Bĩ): Thế khắc ứng, biểu thị thời gian đầu gian nan. Trong quẻ có hợp nhưng cũng có khắc, cho thấy sự bất ổn ban đầu.\nQuẻ biến (Lôi Địa Dự): Là quẻ lục hợp, thế và ứng đồng ngũ hành, biểu thị sự thuận lợi và vui vẻ về sau. \"Dự\" có nghĩa là vui vẻ, liên quan đến \"chấn động\" (Lôi) và \"nhảy đầm trên đất\".\nNgũ hành: \nNhiều Hỏa: Biểu thị nhiều phiền não.\nNhiều Thổ: Biểu thị nhiều tài, nhưng cũng dễ hao tổn.\nHào sơ (Thổ, lâm Bạch Hổ): Biểu thị đất phù màu, dưới nền nhà có xương cốt (mộ cổ). Đây là công thức lý thuyết: Thổ + Bạch Hổ = xương cốt.\nHào hai (Quan quỷ, lâm quẻ Khôn): Biểu thị nhà có vong. Công thức: Hào hai + Quan quỷ + Khôn/Cấn = nhà có vong.\nHào ba (Thê tài, lâm Thanh Long): Nhà có cá thần phụ trợ, biểu thị năng lượng tốt.\nHào sáu (Phụ mẫu, động): Phụ mẫu động khắc tử tôn, biểu thị con cái gặp vấn đề. Tử tôn nằm ở hào năm, bị phụ mẫu ẩn phục, xác nhận con cái có vấn đề.\nNgày Tý, tháng Tuất: Tử tôn suy, càng củng cố nhận định con cái gặp khó khăn.\nHào sáu (Tuất Thổ, Thanh Long): Vượng, biểu thị nhà mạnh về văn thư, vợ tốt, nhiều tài.\nKết luận: \nTình trạng nhà: Nhà có vong, dưới nền có xương cốt, con cái gặp vấn đề, nhưng tài vận tốt nhờ nhiều Thổ.\nNghiệm th"
