    "summary": "Thông tin quẻ:\nNgày: Sửu.\nQuẻ gốc: Thuần Ly (thường và hạ đồng nhau, biểu thị tốt).\nQuẻ biến: Thành Bi.\nHào động: Hào hai, hào năm.\nPhân tích:\nQuẻ gốc (Thuần Ly): Là quẻ lục xung, biểu thị trắc trở trong cuộc sống, đòi hỏi nỗ lực cao. Thường và hạ đồng nhau, nhưng do lục xung nên không hẳn tốt.\nHào hai (Thổ, lâm Thanh Long): Nhà yên ổn, đầy đủ. Thổ được Nguyệt Kiên vượng, lâm Thanh Long nhập trạch, biểu thị nhà hưng vượng.\nHào năm (Tử tôn, lâm Phúc thần): Phúc thần nhập nhà, nhà yên định.\nHào ba (Hỏa, huynh đệ, lâm Bạch Hổ): Bị nhật xung (ngày Hợi, quan quỷ), biểu thị chủ nhà nhiều phiền não, dễ bị bệnh.\nHào sáu (Phụ mẫu, Thổ và Kim vượng): Nhà giàu có, vinh hoa.\nTài động: Tài hóa tử, biểu thị không thuận về quan chức, công danh. Tài động khắc phụ mẫu, dễ gây cãi vã trong nhà.\nSao Câu Trần: Biểu thị tiền kiếm được từ kinh doanh nhà đất, nhưng dễ nhập mộ (hao tổn).\nKết luận:",
    "full_text": "Quẻ 2: Quẻ Thuần Ly biến Thành Bi\nThông tin quẻ: \nNgày: Sửu.\nQuẻ gốc: Thuần Ly (thường và hạ đồng nhau, biểu thị tốt).\nQuẻ biến: Thành Bi.\nHào động: Hào hai, hào năm.\nPhân tích: \nQuẻ gốc (Thuần Ly): Là quẻ lục xung, biểu thị trắc trở trong cuộc sống, đòi hỏi nỗ lực cao. Thường và hạ đồng nhau, nhưng do lục xung nên không hẳn tốt.\nHào hai (Thổ, lâm Thanh Long): Nhà yên ổn, đầy đủ. Thổ được Nguyệt Kiên vượng, lâm Thanh Long nhập trạch, biểu thị nhà hưng vượng.\nHào năm (Tử tôn, lâm Phúc thần): Phúc thần nhập nhà, nhà yên định.\nHào ba (Hỏa, huynh đệ, lâm Bạch Hổ): Bị nhật xung (ngày Hợi, quan quỷ), biểu thị chủ nhà nhiều phiền não, dễ bị bệnh.\nHào sáu (Phụ mẫu, Thổ và Kim vượng): Nhà giàu có, vinh hoa.\nTài động: Tài hóa tử, biểu thị không thuận về quan chức, công danh. Tài động khắc phụ mẫu, dễ gây cãi vã trong nhà.\nSao Câu Trần: Biểu thị tiền kiếm được từ kinh doanh nhà đất, nhưng dễ nhập mộ (hao tổn).\nKết luận: \nTình trạng nhà: Nhà giàu có, yên ổn, nhưng chủ nhà nhiều phiền não, dễ bị bệnh. Tài vận tốt nhưng hao tổn, không thuận về quan chức.\nNghiệm thực tế: \nNhà làm ra tiền nhưng càng về sau càng khó khăn.\nCửa chính và cổng lâm tuyệt mạng, treo gương bát quái chỉ cải thiện phần nào.\nVợ chồng thường bất hòa, thăng quan tiến chức trục trặc.\nHóa giải: \nĐưa vong đi, treo gương bát quái, đặt lại bàn thờ.\nTuy nhiên, do nhà tuyệt mạng, chỉ hóa giải được một phần."
