    "full_text": "Quẻ 3: Quẻ Lý biến Tiểu Súc\nThông tin quẻ: \nNgày: Tân Mùi, tháng Dần.\nQuẻ gốc: Lý (trang 102 trong sách).\nQuẻ biến: Tiểu Súc.\nHỏi bởi: Một phụ nữ về phong thủy nhà ở.\nPhân tích: \nHào thế (Tử tôn, lâm Nguyệt phá): Tử tôn là Phúc thần, bị Nguyệt phá, biểu thị không vui vẻ, tâm trạng lo lắng.\nHào sáu (Nguyên thần, lâm không): Xác nhận tâm trạng không thoải mái, lo lắng.\nHào ba (Huynh đệ, Sửu): Bị Nguyệt xung (Mùi), biểu thị cửa nhà đối diện cửa nhà khác, gây bất lợi phong thủy.\nHào bốn (Phụ mẫu, Ngọ Hỏa, lâm Chu Tước): Động, khắc thế, biểu thị thị phi. Hào bốn là cửa sổ, gặp hợp (Ngọ-Mùi), biểu thị nhà có nhiều cửa sổ, sáng sủa (nhiều Hỏa).\nTài (Sửu, suy): Bị huynh đệ khắc, tài vận không tốt. Tài ẩn phục dưới thế, biểu thị chủ nhà chi ly, giữ tiền kỹ.\nQuan quỷ (Dần, lâm hào ứng): Biểu thị lo lắng về chồng, bệnh tật, hoặc công việc.\nHào năm (Tử tôn, lâm Ngọ Hỏa động): Bị Nguyệt phá, biểu thị con cái hoặc bản thân cần cẩn thận tai nạn xe cộ. Phụ mẫu (xe cộ) và dịch mã (Thân) xác nhận nguy cơ này.\nHào sáu (Huynh đệ, lâm Đằng Xà): Tường rào không thẳng, có khe. Thực tế, một quẻ tương tự cho thấy tường rào cong, có vong phụ nữ tại khúc cua.\nKết luận: \nTình trạng nhà: \nNhà nhiều cửa sổ, sáng sủa, nhưng tài vận không tốt, chủ nhà chi ly về tiền bạc.\nCửa nhà đối diện cửa nhà khác, gây bất lợi.\nTường rào không thẳng, có vong phụ nữ tại khúc cua.\nLo lắng về chồng, con cái dễ gặp tai nạn xe cộ.\nNghiệm thực tế: \nChủ nhà (phụ nữ) và chồng từng ly thân, sau khi hóa giải (đặt cục đá ở hướng Tâ"
