    "summary": "Thông tin quẻ:\nNgày: Không rõ cụ thể.\nQuẻ gốc: Thiên Hỏa Đồng Nhân.\nHỏi về: Phong thủy gia trạch, tình hình gia đạo.\nHào động: Hào hai (Dần Mộc).\nPhân tích:\nQuẻ Thiên Hỏa Đồng Nhân:\nBiểu thị sự đồng lòng, hòa hợp trong gia đình. Tuy nhiên, có yếu tố lục xung, cho thấy vẫn có trục trặc trong gia đạo.\nHào hai (Dần Mộc, lâm Bạch Hổ) động, hóa xuất Sửu Thổ (Phụ mẫu), biểu thị cây ăn trái ở ngoại tỉnh.\nHào hai (Tử tôn, Dần Mộc, lâm Bạch Hổ):\nDần Mộc nằm trong tam hợp Dần-Ngọ-Tuất, biểu thị cây ăn trái (Dần là cây, Ngọ là trái, Tuất là đất chứa). Tuất ở hào sáu (ngoại tỉnh), xác nhận vườn cây ở ngoại tỉnh.\nDần Mộc lâm Bạch Hổ, biểu thị cây lớn bị tổn thương (có thể bị chặt hoặc bệnh).\nHào năm (Thân Kim, lâm Chu Tước):\nHào năm là đường đi, lâm Chu Tước (Hỏa), biểu thị đường rải sỏi hoặc đá dăm (Thân Kim là đá, Chu Tước là Hỏa, liên quan đến đường không bê tông).",
    "full_text": "Quẻ 2: Quẻ Thiên Hỏa Đồng Nhân\nThông tin quẻ: \nNgày: Không rõ cụ thể.\nQuẻ gốc: Thiên Hỏa Đồng Nhân.\nHỏi về: Phong thủy gia trạch, tình hình gia đạo.\nHào động: Hào hai (Dần Mộc).\nPhân tích: \nQuẻ Thiên Hỏa Đồng Nhân: \nBiểu thị sự đồng lòng, hòa hợp trong gia đình. Tuy nhiên, có yếu tố lục xung, cho thấy vẫn có trục trặc trong gia đạo.\nHào hai (Dần Mộc, lâm Bạch Hổ) động, hóa xuất Sửu Thổ (Phụ mẫu), biểu thị cây ăn trái ở ngoại tỉnh.\nHào hai (Tử tôn, Dần Mộc, lâm Bạch Hổ): \nDần Mộc nằm trong tam hợp Dần-Ngọ-Tuất, biểu thị cây ăn trái (Dần là cây, Ngọ là trái, Tuất là đất chứa). Tuất ở hào sáu (ngoại tỉnh), xác nhận vườn cây ở ngoại tỉnh.\nDần Mộc lâm Bạch Hổ, biểu thị cây lớn bị tổn thương (có thể bị chặt hoặc bệnh).\nHào năm (Thân Kim, lâm Chu Tước): \nHào năm là đường đi, lâm Chu Tước (Hỏa), biểu thị đường rải sỏi hoặc đá dăm (Thân Kim là đá, Chu Tước là Hỏa, liên quan đến đường không bê tông).\nThân Kim bị Nguyệt xung (tháng Dần), biểu thị đường gồ ghề, khó đi.\nHào sáu (Tuất Thổ, lâm Câu Trần): \nTuất Thổ là Phụ mẫu, biểu thị đất chứa cây (vườn cây ở ngoại tỉnh). Câu Trần xác nhận yếu tố cũ, đất khô cằn.\nHào bốn (Ngọ Hỏa, lâm Không): \nNgọ Hỏa là quan quỷ, lâm Không, biểu thị công danh không thuận, gia chủ có thể không đi làm hoặc gặp trục trặc trong công việc.\nHào sơ (Tý Thủy, lâm Đằng Xà): \nTý Thủy biểu thị dòng nước ngoằn ngoèo trước nhà, có thể là vệt nước tạm thời do nhà hàng xóm đổ ra.\nKết luận: \nTình trạng nhà: \nNhà có vườn cây ăn trái ở ngoại tỉnh, nhưng cây lớn trước nhà c"
