    "summary": "Thông tin quẻ:\nNgày: Ngày Tuất, tháng Hợi, năm Ngọ.\nHỏi về: Chọn ngày khai trương kinh doanh.\nDụng thần: Thê tài (Mão Mộc).\nQuẻ gốc: Lục hợp (biểu thị sự hòa hợp ban đầu).\nPhân tích:\nDụng thần Thê tài Mão Mộc (trì thế):\nMão Mộc được tháng Hợi sinh, nhị hợp với ngày Tuất, cho thấy tài vận ban đầu tốt, kinh doanh thuận lợi.\nNhật thần Tuất Thổ (Phụ mẫu, hào ứng):\nTuất Thổ nhị hợp với Mão Mộc, hóa Hỏa. Hỏa sinh Tuất Thổ (hào ứng, khách hàng), nhưng không sinh Mão Mộc (Thê tài), dẫn đến tài vận bị khách hàng lấy đi.\nTuất Thổ lâm Bạch Hổ, biểu thị khách hàng có thể gặp vấn đề sức khỏe khi sử dụng sản phẩm/dịch vụ, dẫn đến yêu cầu bồi thường.\nKết luận:\nKinh doanh ban đầu thuận lợi, nhưng về lâu dài sẽ xuống dốc do tài vận bị khách hàng lấy đi. Có nguy cơ khách hàng gặp vấn đề sức khỏe, gây tranh chấp hoặc bồi thường.\nHóa giải:",
    "full_text": "Quẻ 3: Quẻ (Không rõ tên, xem ngày khai trương)\nThông tin quẻ: \nNgày: Ngày Tuất, tháng Hợi, năm Ngọ.\nHỏi về: Chọn ngày khai trương kinh doanh.\nDụng thần: Thê tài (Mão Mộc).\nQuẻ gốc: Lục hợp (biểu thị sự hòa hợp ban đầu).\nPhân tích: \nDụng thần Thê tài Mão Mộc (trì thế): \nMão Mộc được tháng Hợi sinh, nhị hợp với ngày Tuất, cho thấy tài vận ban đầu tốt, kinh doanh thuận lợi.\nNhật thần Tuất Thổ (Phụ mẫu, hào ứng): \nTuất Thổ nhị hợp với Mão Mộc, hóa Hỏa. Hỏa sinh Tuất Thổ (hào ứng, khách hàng), nhưng không sinh Mão Mộc (Thê tài), dẫn đến tài vận bị khách hàng lấy đi.\nTuất Thổ lâm Bạch Hổ, biểu thị khách hàng có thể gặp vấn đề sức khỏe khi sử dụng sản phẩm/dịch vụ, dẫn đến yêu cầu bồi thường.\nKết luận: \nKinh doanh ban đầu thuận lợi, nhưng về lâu dài sẽ xuống dốc do tài vận bị khách hàng lấy đi. Có nguy cơ khách hàng gặp vấn đề sức khỏe, gây tranh chấp hoặc bồi thường.\nHóa giải: \nChọn ngày có địa chi Thìn hoặc Dậu để phá nhị hợp Tuất-Mão, giảm sự ràng buộc tài vận với khách hàng.\nKiểm tra chất lượng sản phẩm/dịch vụ để tránh vấn đề sức khỏe cho khách hàng.\nNghiệm thực tế: \nKhông có thông tin cụ thể về nghiệm lý, nhưng thầy nhấn mạnh rằng việc chọn ngày cần xem xét kỹ để tránh rủi ro lâu dài."
