    "summary": "Thông tin quẻ:\nNgày: Ngày Bính Thìn, tháng Thân, năm Ngọ.\nHỏi về: Chọn ngày cưới cho con trai.\nDụng thần: Thê tài (Dần Mộc).\nQuẻ gốc: Khôn vi Địa.\nQuẻ biến: Trạch Thiên Đoài (Lục xung).\nPhân tích:\nDụng thần Thê tài Dần Mộc (trì thế, phát động):\nDần Mộc bị tháng Thân xung (Nguyệt phá), hóa xuất Quan quỷ (Dậu Kim), biểu thị nguy cơ vợ ngoại tình trong tương lai.\nThân Kim (Huynh đệ) xung Dần Mộc, xác nhận có sự can thiệp từ bên thứ ba.\nQuẻ biến Lục xung:\nBiểu thị hôn nhân không bền vững, có nguy cơ chia tay do ngoại tình.\nPhụ mẫu (hai hào động):\nBiểu thị nhiều giấy tờ hoặc thủ tục liên quan đến hôn lễ, nhưng cũng ám chỉ sự phức tạp trong quan hệ hôn nhân.",
    "full_text": "Quẻ 4: Quẻ Khôn Đoài (Xem ngày cưới)\nThông tin quẻ: \nNgày: Ngày Bính Thìn, tháng Thân, năm Ngọ.\nHỏi về: Chọn ngày cưới cho con trai.\nDụng thần: Thê tài (Dần Mộc).\nQuẻ gốc: Khôn vi Địa.\nQuẻ biến: Trạch Thiên Đoài (Lục xung).\nPhân tích: \nDụng thần Thê tài Dần Mộc (trì thế, phát động): \nDần Mộc bị tháng Thân xung (Nguyệt phá), hóa xuất Quan quỷ (Dậu Kim), biểu thị nguy cơ vợ ngoại tình trong tương lai.\nThân Kim (Huynh đệ) xung Dần Mộc, xác nhận có sự can thiệp từ bên thứ ba.\nQuẻ biến Lục xung: \nBiểu thị hôn nhân không bền vững, có nguy cơ chia tay do ngoại tình.\nPhụ mẫu (hai hào động): \nBiểu thị nhiều giấy tờ hoặc thủ tục liên quan đến hôn lễ, nhưng cũng ám chỉ sự phức tạp trong quan hệ hôn nhân.\nHóa giải: \nChọn ngày có địa chi Hợi để: \nNhị hợp với Dần Mộc, bảo vệ Thê tài.\nXung Thân Kim (Huynh đệ), loại bỏ yếu tố bên thứ ba.\nTránh chọn nhiều ngày Hợi, vì có thể dẫn đến sự kết hợp ngoài ý muốn (ví dụ, vợ liên kết với người ngoài, như \"máy bay bà già\").\nThầy nhấn mạnh rằng hôn nhân giống như \"toilet\": người ngoài muốn vào, người trong muốn ra, cần chọn ngày cẩn thận để tránh rủi ro.\nNghiệm thực tế: \nKhông có thông tin cụ thể, nhưng thầy cảnh báo rằng nếu không hóa giải, hôn nhân có thể gặp trục trặc sau này."
