    "summary": "Thông tin quẻ:\nNgày: Ngày Tuất, tháng Tý, năm Tỵ.\nHỏi về: Chọn ngày chuyển nhà.\nDụng thần: Không xác định rõ, lấy hào thế (Dần Mộc) để xem tổng thể.\nPhân tích:\nHào thế Dần Mộc:\nĐược tháng Tý và ngày Tuất sinh, hóa tiến thần, biểu thị tài vận tốt, công việc có cơ hội thăng tiến.\nPhụ mẫu và Quan quỷ động:\nPhụ mẫu (công ty) và Quan quỷ (công việc) cùng động, biểu thị sự thay đổi cả công việc và công ty.\nQuan quỷ Ngọ Hỏa:\nBị Hợi Thủy khắc, hóa thoái, biểu thị nguy cơ mất chức hoặc mất việc.\nHóa giải:\nChọn ngày Dần để:\nNhị hợp với Hợi, ngăn Hợi khắc Ngọ Hỏa.",
    "full_text": "Quẻ 5: Quẻ Khôn Nguyên Cách (Xem ngày chuyển nhà)\nThông tin quẻ: \nNgày: Ngày Tuất, tháng Tý, năm Tỵ.\nHỏi về: Chọn ngày chuyển nhà.\nDụng thần: Không xác định rõ, lấy hào thế (Dần Mộc) để xem tổng thể.\nPhân tích: \nHào thế Dần Mộc: \nĐược tháng Tý và ngày Tuất sinh, hóa tiến thần, biểu thị tài vận tốt, công việc có cơ hội thăng tiến.\nPhụ mẫu và Quan quỷ động: \nPhụ mẫu (công ty) và Quan quỷ (công việc) cùng động, biểu thị sự thay đổi cả công việc và công ty.\nQuan quỷ Ngọ Hỏa: \nBị Hợi Thủy khắc, hóa thoái, biểu thị nguy cơ mất chức hoặc mất việc.\nHóa giải: \nChọn ngày Dần để: \nNhị hợp với Hợi, ngăn Hợi khắc Ngọ Hỏa.\nDần Mộc là nguyên thần của Ngọ Hỏa, tăng cường năng lượng cho công việc.\nDần là trường sinh của Ngọ, biểu thị sự khởi đầu mới.\nĐề xuất chọn tháng Dần của năm Ngọ (năm sau) để tránh Thái Tuế (năm Tỵ) và đảm bảo Quan quỷ được hỗ trợ bởi Thái Tuế.\nNghiệm thực tế: \nGia chủ chuyển nhà vào ngày Bính Dần, trở nên giàu có nhờ chơi cổ phiếu. Năm sau (năm Ngọ), vào ngày Kỷ Tuất, tháng Dần, gia chủ được lãnh đạo phê duyệt điều động công tác, đúng như dự đoán."
